(window.GIM_TP=window.GIM_TP||{})["Z.Shoftim.0"]={"from":0,"a":[[[],[],[]],[["\u0003רעיא מהימנא\u0004 (דברים ט״ז:י״ח) שׁוֹפְטִים וְשׁוֹטְרִים תִּתֶּן לְךָ בְּכָל שְׁעָרֶיךְ אֲשֶׁר יְיָ' אֱלֹהֶיךָ נוֹתֵן לְךָ וְגוֹ'. בְּפִקּוּדָא דָּא, מָנֵי שׁוֹפְטִים וְשׁוֹטְרִים. וְעוֹד (תהילים ע״ה:ח׳) כִּי אֱלֹהִים שׁוֹפֵט, כִּי י' (מ', מניה) יוֹ\"ד דְּחוּשְׁבָּנֵיהּ כ', כֶּתֶר (בתר) הָכָא, כ' אֱלֹהִים שׁוֹפֵט, זֶה יַשְׁפִּיל ה\"א ה\"א (ה\"ה), וְזֶה יָרִים דָּא (ו\"ו) ו' ו'.","פִּקּוּדָא בָּתַר דָּא, לָדוּן בְּסַיִיף. לָדוּן בְּחֶנֶק. לָדוּן בְּדִין סְקִילָה. לָדוּן בְּדִין שְׂרֵיפָה. לָדוּן בְּסַיִיף לְמַאן, לְסָמָאֵל. הֲדָא הוּא דִכְתִיב, (ישעיהו ל״ד:ה׳) כִּי רִוְּתָה בַשָׁמַיִם חַרְבִּי הִנֵּה עַל אֱדוֹם תֵּרֵד.","חֶרֶב דְּקוּדְשָׁא בְּרִיךְ הוּא, י' רֵישָׁא דְּחַרְבָּא. ו' גּוּפָא דְּחַרְבָּא. הֵ\"א הֵ\"א, תְּרֵין פִּיפִיּוֹת דִּילָהּ. צֶדֶק צֶדֶק תִּרְדּוֹף, חַתְכִין תְּרֵין דִּינִין, דִּינָא מִפִּי בֵּית דִּין דִּלְעֵילָּא, וְדִינָא מִפִּי בֵּית דִּין דִּלְתַּתָּא. וּמֵהָכָא אִשְׁתְּמוֹדָע, אֵין אָדָם נוֹקֵף אֶצְבָּעוֹ מִלְּמַטָּה עַד שֶׁנִּתַּן לוֹ רְשׁוּת מִלְּמַעְלָה.","נַרְתְּקָא דְּחַרְבָּא אֲדֹנָי. תַּמָּן אִשְׁתְּכַח דִּינָא. בְּקְרִיאַת שְׁמַע ידוד. חַרְבָּא דְּקוּדְשָׁא בְּרִיךְ הוּא, עָלָהּ אִתְּמַר (תהילים קמ״ט:ו׳) רוֹמְמוֹת אֵל בִּגְרוֹנָם וְחֶרֶב פִּיפִיּוֹת בְּיָדָם. בְּצַדִּיק חַי עָלְמִין, כָּלִיל חַ\"י בִּרְכָאן, דְּבֵיהּ אֲדֹנָי שְׂפָתַי תִּפְתָּח וּפִי, בֵּיהּ עָאל חַרְבָּא בְּנַרְתִּיקָהּ, (אסתר ז׳:י׳) וַחֲמַת הַמֶּלֶךְ שָׁכָכָה, וּמִתְחַבְּרִין תְּרֵין שְׁמָהָן יְאֲהדוָֹנָהִי.","לָדוּן בְּחֶנֶק, זַרְקָא. תַּמָּן קַו, י' כְּרִיכָא בֵּיהּ, וְקַו, ו' דְּאִתְפַּשְּׁטָא מִנֵּיהּ. בֵּיהּ תָּפִיס לְסָמָאֵל, (במדבר י״ג:כ״ג) וַיִּשָּׂאוּהוּ בַמּוֹט בִּשְׁנָיִם. מַאי מוֹט דְּהַהוּא רָשָׁע. אָדָם דְּאִיהוּ יוֹ\"ד הֵ\"א וָא\"ו הֵ\"א, מַ\"ה, וְד' אַתְוָון ידוד, הֲרֵי תִּשְׁעָה וְאַרְבָּעִים, כְּחוּשְׁבָּן תִּשְׁעָה וְאַרְבָּעִים אַתְוָון, דְּאִינּוּן בְּשִׁית תֵּיבִין דְּיִחוּדָא עִלָּאָה, וּבְשִׁית תֵּיבִין דְּיִחוּדָא תַּתָּאָה, דְּאִינּוּן ו' ו', וְהַאי הוּא וַיִּשָּׂאוּהוּ בַמּוֹט בִּשְׁנָיִם, בְּפִרוּדָא מִנַּיְיהוּ, בְּלָא א' בְּאֶמְצַע וָ\"ו, דְּלֵית יִחוּדָא לְסִטְרָא אַחֲרָא, אֶלָּא וַיִּשָּׂאוּהוּ בַמּוֹט בִּשְׁנָיִם, סָמָאֵל וּבַת זוּגֵיהּ, עוֹלָם הַנִפְרָדִים.","בְּחֶבֶל דְּיֵחָנֵק בָּהּ, אֲחִידָן הֵ\"א הֵ\"א, בְּה' אֶצְבְּעָאן דְּיַד יְמִינָא, וּבְה' דְּיַד שְׂמָאלָא. ו' חֶבֶל. י' חֲנִיקָא דִּלְהוֹן. שְׁמָא דַּיְדוָֹ\"ד, מִיתָה לְסָמָאֵ\"ל וְנָחָשׁ, וְחַיִּים לְיִשְׂרָאֵל. (עיין בראשית כ\"ב ע\"ב) וּבְגִין דָּא (דברים ל״ב:ל״ט) רְאוּ עַתָּה כִּי אֲנִ\"י אֲנִי הוּא וְאֵין אֱלֹהִים עִמָּדִי. אֲנִי אָמִית לֵאלֹהִים אֲחֵרִים בִּשְׁמִי, וּלְכָל דְּלָא הֵימְנוּ בִּי. וַאֲחֲיֶּה לְאִינּוּן דְּהֵימְנִין וְנַטְרִין פִּקּוּדִין דִּילִי.","לָדוּן בִּסְקִילָה לְסָמָאֵל, בְּאֶבֶן דְּאִיהִי יוֹ\"ד, זָרִיק לָהּ (צדיק) לְגַבֵּיהּ, בַּחֲמֵשׁ אֶצְבְּעָאן דְּאִינּוּן ה', וּבַקָּנֶה דִּדְרוֹעָא דְּאִיהוּ ו', וּבַכָּתֵף דְּתַמָּן ה'. וְזָרִיק לָהּ לְגַבֵּיהּ מַחֲשָׁבָה, דְּאִיהוּ שְׁמָא מְפֹרָשׁ יוֹ\"ד הֵ\"א וָא\"ו הֵ\"א.","לָדוּן בִּשְׂרֵפָה לְסָמָאֵל. עֵצִים לְאַדְלְקָא בְּהוֹן נוּרָא. זַכָּאָה אִיהוּ גּוּפָא דְּאִיהוּ עֵץ, וְאֵבָרִים דִּילֵיהּ עֵצִים, לְאוֹקְדָא בְּהוֹן אֶשָּׁא, דְּאִיהוּ נֵר מִצְוָה, בְּכָל אֵבֶר, לְאוֹקְדָא לְסָמָאֵל, בִּשְׁכִינְתָּא עִלָּאָה, בְּעֵץ דְּאִיהוּ תִּפְאֶרֶת, וּבְכָל עֵצִים דַּאֲחִידָן בֵּיהּ. דִּבְזִמְנָא דְּאֵשׁ עַל גָּבוֹהַּ נָחִית הֲוָה, עַל גַּבֵּי עֵצִים דְּקָרְבְּנָא, (במדבר א׳:נ״א) וְהַזָּר הַקָּרֵב יוּמָת, דְּאִתּוֹקַד בֵּיהּ. הֲדָא הוּא דִכְתִיב, (ויקרא ו׳:ה׳) וְהָאֵשׁ עַל הַמִּזְבֵּחַ תּוּקַד בּוֹ. זַכָּאָה אִיהוּ מַאן דְּאָחִיד בְּאִילָנָא דְּחַיֵּי, בְּגוּפֵיהּ, בְּאֵבָרִים דִּילֵיהּ, נֵר כָּל עַנְפָא וְעַנְפָא נֵר מִצְוָה ברמ\"ח פִּקּוּדִין דִּילֵיהּ.","כַּד אֲחִידָן בֵּיהּ תַּרְוַויְהוּ, יִתְקְיָּים (שמות ג׳:ב׳) וַיַּרְא וְהִנֵּה הַסְּנֶה בּוֹעֵר בָּאֵשׁ וְהַסְּנֶה אֵינֶנּוּ אוּכָּל. וְסָמָאֵל וְנָחָשׁ וְכָל מְמָנָן דִּילֵיהּ, דְּאִינּוּן קוֹצִין, אִתּוֹקָדוּ. וַעֲנְפִין דִּסְנֶה, וְאִיבָּא דִּילֵיהּ, וְעָלִין דִּילֵיהּ, לָא אִתּוֹקָדוּ. דָּא אַחְזֵי לֵיהּ קוּדְשָׁא בְּרִיךְ הוּא.","אָמַר בּוּצִינָא קַדִּישָׁא, וַדַּאי יִשְׂרָאֵל אִינּוּן עֵצִים יְבֵשִׁים בְּאוֹרַיְיתָא, בְּגִין דַאֲחִידוּ בְּאֵשׁ דְּהֶדְיוֹט, לָאו אִינּוּן כַּדְּקָא חֲזִי, לְמֶעְבַּד בְּהוֹן נִיסָא, מִיַּד דְּאַנְתְּ נְחִיתַת עָלַיְיהוּ בְּאוֹרַיְיתָא, בְּגִינָךְ נָחַת עָלַיְיהוּ אִילָנָא דְּחַיֵּי, וּמִצְוָה דְּאִיהוּ נֵר יְיָ' וַאֲחִידַת בְּהוֹן וְיֵהוֹן חַיִּין. וְאוּמִין עוֹבְדֵי כּוֹכָבִים וּמַזָּלוֹת דְּעָלְמָא, אִתּוֹקְדָן בְּהַהוּא נֵר. וְהַאי אִיהוּ דְּאָמַר נָבִיא, (ירמיהו מ״ו:כ״ז) וְאַתָּה אַל תִּירָא עַבְדִי יַעֲקֹב וְאַל תֵּחַת יִשְׂרָאֵל כִּי אִתְּךָ אָנִי וְגוֹ'."],[[0,"שופטים ושוטרים תתן וגו':","במצוה זו צוה על שופטים ושוטרים. ועוד. כי אלקים שופט כי' \u0003ם'\u0004, מניה \u0003י\u0004 ו\"ד דחושבניה \u0003כ'\u0004 לאחר מכאן, אלקים שופט, זה ישפיל \u0003ה\"ה\u0004 דהויה וזה ירום \u0003ו\"ו\u0004 דהויה."],[0,"","פירוש. סוד המשפט הוא בג' קוין, בסוד במותב בי תלתא כחדא הוינא. הרומזים על ג' קוין המשמשים כאחד. אשר קו הימין נוטה לחסד, ושופט העולם בחסד. וקו שמאל נוטה לדינים ושופט העולם בדין וקו האמצעי מכריע ביניהם, ומקיים הארת שניהם, אלא שמשפיל את הארת השמאל שלא יאיר אלא ממטה למעלה (כנ\"ל ב\"א דף ס' אות נ' ד\"ה מחלוקת) ואז אין בו דינים, ומרים הארת הימין שיאיר ממעלה למטה, שה\"ס אור ג\"ר. כמ\"ש שם."],[0,"","וזה אמרו, \u0003ועוד\u0004. דהיינו בדרך סוד, \u0003כי אלקים שופט, כי, מ'\u0004, שהמלה \u0003כי\u0004 בגי' \u0003מ'\u0004, כי \u0003מניה יוד דחושבניה כ'\u0004, כי ה \u0003י'\u0004 של המלה כי, במילואה, דהיינו \u0003יוד\u0004, הוא בגי' עשרים. ועם ה \u0003כ'\u0004 עצמה של המלה כי, הרי הוא בגי' \u0003מ'\u0004. ומ' יורה על קו ימין שהוא חסד. \u0003בתר הכא\u0004, לאחר מכאן שהקו ימין, המרומז בהמלה כי, שפט, \u0003אלקים שופט\u0004, שהוא הקו שמאל, שהקו ימין שה\"ס \u0003כי\u0004, שופט העולם בחסד, והקו שמאל שה\"ס \u0003אלקים\u0004 שופט העולם בדין. ואחריהם בא קו האמצעי שנקרא \u0003זה\u0004, וז\"ש, \u0003זה ישפיל ה\"ה\u0004, שקו אמצעי הנקרא \u0003זה\u0004, משפיל את \u0003ה\"ה\u0004 שה\"ס השמאל, והמלכות, שמשפיל שלא יאיר השמאל בה, אלא ממטה למעלה, דהיינו רק בו\"ק. \u0003וזה ירום ו\"ו\u0004, שמרים את קו ימין המאיר בז\"א בחסדים, שהוא יאיר ממעלה למטה באורות דג\"ר. (כמ\"ש לעיל ב\"א דף ס' אות נ' ד\"ה מחלוקת)."],[1,"פקודא בתר דא וכו':","המצוה שלאחר זו, הוא לדון בחרב, לדון בחנק, לדון בדין סקילה, לדון בדין שריפה. \u0003לדון בחרב\u0004, למי. ומשיב, לסמאל. ז\"ש, כי רותה בשמים חרבי הנה על אדום תרד. דהיינו על סמאל, שהוא שרו של אדום."],[2,"חרב דקב\"ה י' וכו':","החרב של הקב\"ה \u0003י'\u0004 של הויה, היא ראש החרב. ה \u0003ו'\u0004 של הויה היא גוף החרב, \u0003ה' ה'\u0004 של הויה, הן ב' פיות של החרב, שהם סוד צדק צדק תרדוף, שחותכים שני דינים, דין מפי בית דין שלמעלה, ודין מפי בית דין שלמטה. ומכאן נודע, שאין אדם נוקף אצבעו מלמטה עד שניתן לו רשות מלמעלה."],[2,"","פירוש. המוחין דז\"א המתגלים ביחוד קריאת שמע, מכונים חרב שעל ידיה נשמדת הסטרא אחרא. כלהלן. ועיקר גילוי המוחין ההם, הוא ע\"י התחברות המלכות בבינה, שאז מקבלת המלכות כלים דבינה בסוד אמא אוזיפת לברתא מאנהא (כנ\"ל בהקדמת ספר הזהר אות י\"ז) ולולא זה לא היו ז\"א ומלכות ראוים למוחין כלל (כנ\"ל ב\"א דף ז' אות ג' ד\"ה וכבר). וע\"כ יש לבינה ומלכות אותה צורת אות. דהיינו \u0003ה'\u0004 כי הן אותם המוחין. ולפיכך הן בצורה אחת בפי החרב, אלא שנבחנות לב' פיות, כמו בשם שהן ב' ההין."],[2,"","וז\"ש, \u0003י' רישא דחרבא\u0004, שה\"ס החכמה והיא \u0003י'\u0004 דהויה שהיא ראש הכל, המשפיע המוחין אל \u0003ה'\u0004 עליונה, שהיא בינה. אמנם כשהמוחין בי\"ה, אינם יכולים להשמיד הס\"א, כי הס\"א אינו נאחז בהם, אלא בו\"ה, וע\"כ רק ו\"ה יכולים להשמיד הס\"א. וז\"ש \u0003ו' גופא דחרבא\u0004, כי ז\"א שה\"ס \u0003ו'\u0004 דהויה הוא עיקר החרב המשמיד הס\"א. \u0003ה' ה', תרין פיפיות דילה\u0004, שע\"י השואת הצורה שלהן באים המוחין לכלל גילוי כנ\"ל, ולפיכך אינו מספיק פה אחד, אלא צריכים דוקא לב' פיות, שסוד הפה שבבינה ישפיע לפה של המלכות באפן אשר ה \u0003י'\u0004 שהיא ראש הכל משפיעה אל \u0003ה'\u0004 ראשונה, ומהן מקבלת ה \u0003ו'\u0004 שהיא גוף ועיקר החרב, משפיעה ל \u0003ה'\u0004 אחרונה, ואז נשלמת המציאות של החרב. וז\"ש, \u0003צדק צדק תרדוף\u0004 שב' פיות החרב נקראים צדק צדק, וב' פיות החרב האלו, \u0003חתכין תרין דינין, בבת אחת, דינא מפי ב\"ד דלעילא\u0004, דהיינו בינה. \u0003ודינא מפי ב\"ד דלתתא\u0004, דהיינו מלכות. וז\"ש \u0003ומהכא אשתמודע אין אדם נוקף אצבעו מלמטה\u0004, דהיינו על פי דין של ב\"ד של מטה, \u0003עד שנתן לו רשות מלמעלה\u0004, דהיינו ע\"י ב\"ד של מעלה, שהוא בינה. כי כל המוחין שבמלכות, מקובלים מן הבינה, ואין למלכות מבחינת עצמה כלום."],[3,"נרתקא דחרבא אדני וכו':","הנרתק של החרב, דהיינו הכלי שטומנים בו החרב, הוא השם \u0003אדני\u0004. שם, באדני, נמצאות אותיות דין. כי באדני יש אותיות א' דין. בקריאת שמע, ה\"ס \u0003הויה\u0004, שהוא חרבו של הקב\"ה, כנ\"ל בדבור הסמוך. עליה נאמר רוממות אל בגרונם וחרב פיפיות בידם, כמ\"ש לעיל. בצדיק ח\"י העולמים כלולות שמונה עשרה ברכות, כלומר שע\"י הצדיק, שהוא יסוד דז\"א נעשה זווג ז\"א ומלכות דגדלות, שה\"ס שמונה עשרה ברכות, שבתפלת העמידה. דביה אדני שפתי תפתח, \u0003ופי\u0004, שהיסוד פותח את המלכות שנקראת אדני. ובו, ביסוד, נכנסת החרב בנרתיקה, שה\"ס זווג הויה, באדני, שנעשה ע\"י היסוד וחמת המלך שככה. כי כבר נתבערו הקליפות ביחוד דקריאת שמע, ועתה בתפלת העמידה אין עוד אחיזה להן ונשקט הכעס, ומתחברים ב' השמות \u0003יאהדונה\"י\u0004, שהוא שילוב ב' שמות, הויה אדנ\"י."],[4,"לדון בחנק זרקא וכו':","המצוה לדון בחנק. בהטעם זרקא, יש שם קו, ו \u0003י'\u0004 כרוכה עליו, וקו, הוא \u0003ו'\u0004 שנתפשטה מן ה \u0003י'\u0004. בו ב \u0003ו'\u0004, תופש את סמאל. בסו\"ה, וישאוהו במוט בשנים. מהו מוט של אותו רשע סמאל. ומשיב, אדם שהוא יוד הא ואו הא שבגי' מ\"ה, ועם ד' אותיות הויה, הרי מ\"ט, כחשבון מ\"ט אותיות שהן ב \u0003ו'\u0004 מלים של יחוד העליון, שהוא שמע ישראל, וב \u0003ו'\u0004 מלים של יחוד התחתון, שהוא בשכמל\"ו. שהן \u0003ו' ו'\u0004. וזה הוא וישאוהו במוט בשנים, בפרוד מהן, בלא \u0003א'\u0004 שבאמצע \u0003ו\"ו\u0004, כי אין יחוד לסטרא אחרא, אלא וישאוהו במוט בשנים, סמאל ובת זוגו עולם הנפרדים."],[5,"בחבל דיחנק בה וכו':","בחבל שיחנק בו את סמאל, אחוזות הא הא, דהיינו ב \u0003ה'\u0004 אצבעות דיד ימין, וב \u0003ה'\u0004 אצבעות דיד שמאל. ה \u0003ו'\u0004 היא חבל. ה \u0003י'\u0004 החניקה שלהם של סמאל ונחש. השם הויה, הוא מיתה לסמאל ונחש, וחיים לישראל. ומשום זה כתוב, ראו עתה כי אני אני הוא ואין אלקים עמדי \u0003אני אמית\u0004 לאלהים אחרים בשמי, ולכל שאינם מאמינים בי. \u0003ואחיה\u0004 לאלו המאמינים בי ושומרים מצוותי."],[6,"לדון בסקילה לסמאל וכו':","לדון בסקילה לסמאל, הוא באבן שהיא \u0003י'\u0004, וזורק אותה אליו בחמש אצבעות שהן \u0003ה'\u0004, ובקנה הזרוע, שהוא \u0003ו'\u0004, ובכתף, ששם \u0003ה'\u0004, והמחשבה זורקת את האבן אליו, שהיא שם המפורש, יוד הא ואו הא."],[7,"לדון בשרפה לסמאל וכו':","לדון בשרפה לסמאל, על ידי עצים להדליק בהם אש. אשרי הוא הגוף שהוא עץ, והאברים שלו הם עצים, שישרוף בהם אש, שהוא נר מצוה, בכל אבר, לשרוף את סמאל על ידי השכינה העליונה, שהיא בינה, בעץ שהוא תפארת, ובכל עצים, דהיינו הספירות, האחוזים בת\"ת. כי בעת שאש של גבוה יורדת על העצים של הקרבן, והזר הקרב יומת, כי נשרף בה, באש. ז\"ש והאש על המזבח תוקד בו. אשרי הוא מי שאחוז בעץ החיים, שהוא ז\"א, בגופו, ובאברים שלו. שהוא נר, כל ענף וענף הוא נר מצוה ברמ\"ח מצות שלו. שהם כנגד רמ\"ח אברים, דהיינו נר מצורן על כל אבר."],[8,"כד אחידן ביה וכו':","כששניהם דהיינו עץ החיים ונר מצוה, שהם ז\"א ומלכות, אחוזים בו, באותו האדם, יתקיים, וירא והנה הסנה בוער באש והסנה איננו אוכל דהיינו האדם, וסמאל ונחש וכל הממונים שלו האחוזים בגוף האדם, שהם קוצים, יהיו נשרפים, והענפים של הסנה, והפירות שלו, והעלים שלו, אינם נשרפים. זה הראה הקב\"ה למשה."],[9,"אמר בוצינא קדישא וכו':","אמר המאור הקדוש שהוא ר\"ש. לרעיא מהימנא, ודאי ישראל הם עצים יבשים בתורה כי משום שאחוזים באש של הדיוט אינם ראוים שיעשה להם נס. ומיד שאתה יורד עליהם בתורה, בשבילך יורד עליהם עץ החיים, שהוא ז\"א, ומצוה, שהיא מלכות, שהיא נר ה', ואוחזת בהם והם יחיו. ואומות העולם עכו\"ם, יהיו נשרפים בנר ההוא. וזה שאמר הנביא, אל תירא עבדי יעקב אל תחת ישראל כי אתך אני וגו'."],[9,"","ביאור המאמר. כבר ידעת שזו\"ן מצד אצילותם אינם ראוים למוחין, משום שמלכות דצמצום א' רובצת עליהם שאינה ראויה לקבלת אור, ובאפן זה, לא היה קיום לזו\"ן ולכל העולמות הנמשכים מהם ע\"כ בכדי שהעולם יוכל להתקיים, העלה המאציל את המלכות לבינה. ונעשית אחת עם הבינה, ואז נעשו זו\"ן ראוים למוחין, (כמ\"ש לעיל ב\"א דף ז' ד\"ה וכבר ע\"ש). וכל זה, אם התחתונים הולכים בדרך הישר. אבל אם התחתונים חוטאים, יש רשות לסטרא אחרא להתדבק בזו\"ן ולגלות בחינת המלכות דצמצום א' שיש בכלים דזו\"ן, ואז מסתלקים כל האורות. וכל זמן שהס\"א דבוקה במלכות זו ויונקת ממקום החסרון הזה שבזו\"ן, אז אין תקוה שזו\"ן יוכלו לקבל מוחין להשפיע אל העולמות. ולפיכך אין שום עצה אלא להמית את הסטרא אחרא זו שנתדבקה בזו\"ן. ואז אפשר לזו\"ן להשפיע שוב חיים אל העולמות. ושני אלה באים כאחד כי עם תקון זו\"ן שימשיכו החיים, מתים הס\"א (כמ\"ש באות ו') \u0003שמא דהויה, מיתה לסמאל\u0004. שבהתתקן שם הויה, דהיינו המוחין דזו\"ן, מתים הס\"א שהיו אחוזים במקום החסרון שלהם."],[9,"","אמנם להמית הס\"א ולהמשיך החיים אל זו\"ן והעולמות, אי אפשר עד שימיתו אותו, בד' מיתות, סקילה, שרפה, הרג, וחנק. כי אינו מתבטל לגמרי עד שיעברו עליו ד' מיתות אלו. והענין הוא, כי כדי להחזיר המוחין לקדמותם בשלמות, צריכים ד' מיני תקונים. \u0003תקון הא'\u0004 הוא להפרידו מדבקות המלכות דצמצום א', כי כל זמן שהס\"א דבוק שם אין לחשוב אפילו מבחינת תקון. וזה עושים בסוד מוקש שמשימים לו (כנ\"ל וארא אות ק\"ט) כי מעלים את המלכות לבינה, ומקבלת הבינה דינים דמלכות ואז נמשך גם הס\"א לינק מן החסרון שבבינה, ועוזב את החסרון שבמלכות והוא נפרד ממנה. כי כל תקות הס\"א הוא להאחז במדרגות עליונות. וכיון שהס\"א נתדבקה בחסרון הבינה, אז מורידים המלכות מן הבינה, והבינה חוזרת לשלמותה, והס\"א נפרדת גם מאחיזת הבינה. ותקון זה נקרא זרקא, כי זורקים המלכות למעלה שתתדבק בבינה. וכן נבחן \u0003למיתת סקילה.\u0004 כי המלכות מכונה אבן, וזריקתה למעלה להדבק בבינה, נופל כוחה על ראש הס\"א, כי עי\"ז הוא נפרד מן המלכות דצמצום א'. שלולא זה אין מציאות לשום תקון."],[9,"תקון הב'","הוא, כי אחר ירידת המלכות מן הבינה, יוצא בה קו השמאל, ושוב נאחז הס\"א בהארה זו דשמאל למשוך אותה ממעלה למטה שבזה שוב סותם את האורות, והשמאל אינו יכול להדבק עם הימין. ונעשית מחלוקת ביניהם (כנ\"ל אד\"ר אות רי\"ד) ובזה הוא מחטיא את התחתונים, בסו\"ה יעלו שמים ירדו תהומות. כמ\"ש שם. וכדי לגרשו משם יורד מקו שמאל דבינה אש שורפת, שלא יוכל הס\"א לקרב לינק משם, בסוד והזר הקרב יומת. ותקון זה נקרא \u0003מיתת שרפה\u0004 לס\"א. אמנם עוד אינו מספיק, שהשמאל יתיחד עם הימין, ויפתחו האורות. אלא שמספיק להפריד הס\"א שלא יוכל לינק משמאל, מחמת שהוא אש שורפת."],[9,"תיקון ג'",", וכדי לפתוח האורות, צריכים לתקון דקו אמצעי, שהוא ימעט את הג\"ר דשמאל, שאז נכנע השמאל ומתיחד עם הימין, וכיון שקו אמצעי ממעט את ג\"ר דשמאל נהרגת הס\"א, שכל חיותה היא מדביקות בשמאל. שז\"ס \u0003רותה בשמים חרבי\u0004, כי המסך דחירק, שה\"ס החרב הממעטת ג\"ר דשמאל, הנה עיקר פעולתה היא בשמים, שה\"ס קו אמצעי, למעלה, אבל לבסוף \u0003על אדום תרד\u0004, שבחרב הזו נהרגת הס\"א כי נחרבה יניקתה. ותקון זה נקרא \u0003מיתת הרג\u0004, שהס\"א נהרגת בחרב, שהוא ע\"י קו האמצעי. אמנם עוד לא נשלם בזה ביטול הס\"א לגמרי, כי אין הס\"א מתבטלת לגמרי אלא בהארת חכמה, וכיון שמדרך קו האמצעי, שהוא ז\"א, להמשיך רק חסדים, ע\"כ עוד נשאר איזה כח לס\"א, כי יש לו עוד מקום חסרון להתאחז בו."],[9,"תקון ד'",", וכדי להחניק את הס\"א לגמרי צריכים ליחוד ז\"א ומלכות, כי מקום גילוי החכמה הוא במלכות, ומקום גילוי החסדים הוא בז\"א, וכשמתיחדים שניהם נעשו ז\"א ומלכות לאחד, וכן הארת החכמה והארת החסדים נעשו לאחד, ואז נחנקת הס\"א לגמרי, שלא נשאר לה מקום ריקן וחסרון בקדושה להאחז בו. ותקון זה נקרא \u0003מיתת חניקה\u0004, כי הס\"א נחנקת מחוסר נשימה מן הקדושה, ועוברת מן העולם, אלא אם התחתונים יחזרו לסורם יחיו שוב את הס\"א ע\"י עונותיהם. והנה נתבארו סוד ד' מיתות, סקילה שריפה הרג וחנק, שאין הס\"א עובר מן העולם, טרם שיעברו עליו ד' מיתות אלו."],[9,"","וז\"ש (באות ז') \u0003לדון בסקילה לסמאל באבן דאיהי י'\u0004, שהסקילה ה\"ס \u0003י'\u0004 דהוי\"ה, והאבן היא מלכות שנקראת אבן, וע\"י שזורקים את האבן, עד מקום ה \u0003י'\u0004 דהויה, ה \u0003י'\u0004 דהוי\"ה סוקלת את הס\"א, והוא נפרד מן הקדושה כנ\"ל. וגם המלכות שעלתה לבינה בסוד ה \u0003י'\u0004, נקראת ג\"כ, \u0003י'\u0004 שנכנסה באור הבינה ונעשה האור לאויר (כנ\"ל ב\"א דף מ\"ד ד\"ה בקע). וסוד ה \u0003י'\u0004 דהויה היא א\"א ואו\"א, כי המלכות עולה עד הבינה שבראש דא\"א, ובינה ותו\"מ דראש א\"א יוצאים מחמת זה מראש דא\"א לבחינת חג\"ת דא\"א, שנקראים ידים, ואח\"כ שמורידים המלכות מן הבינה, ובינה ותו\"מ דראש א\"א חוזרים לראש, מעלים גם כן, התחתון שלהם, שהוא החג\"ת דא\"א אל מדרגת ראש דא\"א, ונעשו חב\"ד דא\"א. שז\"ס שאו ידיכם קדש. כי בזה נושאים הידים מבחינת גוף לבחינת ראש. ולולא עלית המלכות לראש א\"א, לא היו חג\"ת דא\"א ראוים לאור להיותם בחינת ז\"א דא\"א, שהוא התכללות מז\"א דאצילות. ולפיכך נבחן שידים אלו זורקות האבן לראש הס\"א, וסוקלות אותו. כי ע\"י המוחין שמקבלים נסקל הס\"א (כנ\"ל באות ו') \u0003שמא דהויה מיתה לסמאל ונחש וחיים לישראל.\u0004"],[9,"","וז\"ש (באות ז') \u0003זריק לה לגביה בחמש אצבען דאינון ה', ובקנה דדרועא דאיהו ו', ובכתף דתמן ה'.\u0004 כי כשעולות הידים לראש א\"א, נעשה בכל יד ע\"ס, חב\"ד חג\"ת נהי\"מ שהאצבעות, נעשו חב\"ד, וה\"ס ה' דהויה, וקנה הזרוע, נעשה חג\"ת, שה\"ס \u0003ו'\u0004 דהויה, והקבורת המחוברת לכתף, נעשית נהי\"מ שבהם המלכות, שה\"ס \u0003ה'\u0004 אחרונה דהויה. וכל ע\"ס אלו יצאו בסבת עלית המלכות לבינה דא\"א וירידתה, ע\"כ נבחן שהם זורקים האבן על ראש הס\"א וסוקלים אותו. וז\"ש, ש \u0003ה' ו' ה'\u0004 שביד, הם הזורקים את האבן. ונודע, שידים דא\"א, נעשו מוחין לז\"א, וז\"ש, \u0003וזריק לה לגביה מחשבה, דאיהו שמא מפרש, יוד הא ואו הא,\u0004 כי הידים דא\"א נעשו מחשבה, לז\"א, שה\"ס המוחין המרומזים בהויה במילוי אלפין, הנקרא שם המפורש. שהם הסוקלים את הס\"א, בסוד, \u0003שמא דהויה מיתה לסמאל\u0004. כנ\"ל. והנה נתבאר תקון הא' שהוא \u0003מיתת סקילה\u0004 לס\"א. שבאה מן ה \u0003י'\u0004 דהויה, מכח עלית המלכות לבינה של \u0003י'\u0004 הזו, וירידתה משם. ועתה מבאר ענין מיתת השרפה הבאה מן \u0003ה'\u0004 דהויה."],[9,"","וז\"ש (באות ח') \u0003לדון בשרפה לסמאל\u0004 וכו' \u0003לאוקדא לסמאל בשכינתא עלאה בעץ דאיהו תפארת\u0004 וכו'. כי אחר שירדה המלכות מן הבינה דא\"א, היא יורדת מבינה שבכל המדרגות, ואז יוצא בבינה, שה\"ס ישסו\"ת, קו שמאל שהוא לוהט עם רוב הדינים שבו, שהוא אש שורפת, כדי להפריד הס\"א, שלא תמשיך החכמה ממנו ממעלה למטה. ועיקר פעולתו לשרוף את הס\"א נעשה כשהקו האמצעי ממשיך הדינים ההם למקומו (כנ\"ל פקודי אות שע\"ו) וז\"ש, \u0003לאוקדא לסמאל בשכינתא עלאה\u0004, שהיא בינה, שבקו שמאל שלה אש שורפת, \u0003בעץ דאיהו תפארת\u0004 וכו', שפעולת השריפה היא בעת שהאש נאחז בקו האמצעי שנקרא תפארת, ואז הוא שורף הס\"א. וז\"ש, \u0003דבזמנא דאש של גבוה\u0004, דהיינו האש דקו שמאל דבינה, \u0003נחית ע\"ג עצים דקרבנא\u0004, ששם מקום גילוי של הדינים ההם, אז והזר הקרב יומת, שהס\"א הקרב לינק מקו שמאל תיכף ישרף ויומת. והנה נתבאר ענין תקון הב', שהוא \u0003מיתת שרפה\u0004 הבאה מן \u0003ה'\u0004 דהויה, דהיינו מקו שמאל דישסו\"ת. ועתה מבאר ענין מיתת ההרג, הבאה מן \u0003ו'\u0004 דהויה, שהיא קו האמצעי."],[9,"","וז\"ש (באות ב') \u0003לדון בסייף למאן לסמאל, הה\"ד, כי רותה בשמים חרבי הנה על אדום תרד.\u0004 שהוא בעת שקו האמצעי מיחד ימין ושמאל, שלא יוכל ליחדם זולת ע\"י שממעט הג\"ר דקו שמאל (כנ\"ל לך דף י\"ג ד\"ה ונתבאר) שמיעוט הזה נעשה בשמים. אמנם הס\"א נהרגת מחמתו מחמת שכל חיותו הוא מג\"ר דשמאל אלו, ונחשב כמו שנחתך ראשו דס\"א, כי הג\"ר נקראות ראש. וזסו\"ה \u0003רותה בשמים חרבי\u0004, כי המסך דחירק מעביר הג\"ר דשמאל בשמים, ושם השמאל מתגדל על ידי זה, כי נתחבר בחסדים דימין, ומאיר בהארה גדולה, אבל הראש דס\"א, נכרת מחמת מיעוט הג\"ר הללו, וז\"ש, \u0003הנה על אדום תרד\u0004. שהוא סמאל שרו של אדום. וז\"ש, (באות ג') \u0003חרב דקב\"ה, י' רישא דחרבא, ו' גופא דחרבא, הא הא תרין פיפיות דילה\u0004, ה \u0003י'\u0004 היא שורש החרב, כי ה \u0003י'\u0004 היא שורש הכל. אבל גוף החרב הוא ה \u0003ו'\u0004, שהיא ז\"א, קו האמצעי, שהוא הפועל וממעט את ג\"ר דשמאל כדי ליחדו עם הימין. אמנם הוא ממעט בכח המסך דחירק, בב' פעולות, מתחילה בכח המלכות, ואח\"כ בכח המלכות הממותקת בבינה (כנ\"ל לך דף י\"ג ד\"ה ונתבאר) וז\"ס ב' פיות החרב, שבהם כורת וממעט את הג\"ר דשמאל, שהם \u0003ה'\u0004 עלאה, דהיינו, מלכות הממותקת ב \u0003ה'\u0004 עלאה, וה' תתאה, דהיינו המלכות עצמה. וז\"ש \u0003צדק צדק תרדוף, חתכין תרין דינין\u0004 דהיינו ב' כחות המיעוט, \u0003דינא מפי ב\"ד דלעילא\u0004, שה\"ס בינה, \u0003ודינא מפי ב\"ד דלתתא\u0004, שה\"ס מלכות. \u0003ומהכא אשתמודע אין אדם נוקף\u0004 וכו', כלומר, שהמלכות אינה ממעטת הג\"ר מכחה עצמה אלא מכח הבינה. כי אחר שנמתקה בבינה, אינה פועלת עוד כלום מכחה עצמה. כי בחינתה עצמה נגנזת."],[9,"","וז\"ש (באות ד') \u0003נרתקא דחרבא אדני תמן אשתכח דינא\u0004, שאע\"פ שאמרנו ה' ה' ב' פיות שלה, אין הפירוש בזווג הויה אדני אלא בבחינת הויה, מטרם שנזדווג עם אדני, כי אז נמצאים הדינים בבחינת מלחמה עם הס\"א והדינים שבב' ההין הם חותכים הראש דס\"א כנ\"ל. אבל בשם \u0003אדני תמן אשתכח דינא\u0004, דהיינו שהדין שבמלכות נתעלה ונמתק כל כך עד שנעשה שם קדוש אדני, כי השם אדני הוא אותיות \u0003א' דין\u0004. ולפיכך נבחן שהוא נרתק להויה, כלומר שהזווג הויה אדני הוא אחר שכלו כל המלחמות, והחרב המרומזת בהויה נכנסת לנדנה, כי אין עוד קליפות ללחום עמהם. וז\"ש, \u0003בק\"ש הויה חרבא דקב\"ה\u0004, שהיחוד שבקריאת שמע הוא בבחינת חרבו של הקב\"ה לכרות ראש הס\"א, כי בק\"ש אין עוד היחוד בשלמות בבחינת ג\"ר, מחמת שיש עוד מלחמות עם הס\"א לכרות ראשו בחרב, וכן לחנוק אותו עם יחוד התחתון שבבשכמל\"ו, כלהלן, אבל ביחוד הוי\"ה אדני שבתפילה, כבר כלו כל המלחמות, והחרב, שה\"ס הויה, ש \u0003י'\u0004 ראש החרב, ו \u0003ו'\u0004 גוף החרב, ו \u0003ה' ה'\u0004 ב' פיפיות שלה, כנ\"ל, אותה החרב נכנסת לנרתיקה שהוא השם אדנ\"י. שז\"ס היחוד הויה אדני שבתפלת שמונה עשרה, שאין צריכים יותר לכלי מלחמה. וז\"ש \u0003בצדיק ח\"י עלמין\u0004, שהוא יסוד דז\"א, \u0003כליל ח\"י ברכאן\u0004, שהוא בזווג דתפלת שמונה עשרה ברכות, \u0003דביה, אדני שפתי תפתח. ופי, ביה עאל הרבא בנרתיקה\u0004, כי כמו שהחרב יש לה ב' פיות מטעם הדין של בינה ומלכות, כן בדין המתוק של אדני יש כנגדם ב' פיות דבינה ומלכות, להכניס בהם ב' פיות החרב. שז\"ס אדני \u0003שפתי\u0004 תפתח, שהוא פה אחד \u0003ופי\u0004 יגיד היא פה השני, ואז \u0003וחמת המלך שככה\u0004. כי כלו כל המלחמות. \u0003ומתחברין תרין שמהן יאהדונהי.\u0004 והנה נתבאר \u0003מיתת הרג\u0004, בחרב. ועתה מבאר מיתת חנק."],[9,"","וז\"ש (באות ה') \u0003זרקא תמן קו י' כריכא ביה\u0004, זרקא ה\"ס זריקת המלכות לבינה, כנ\"ל במיתת סקילה, ואומר \u0003תמן קו\u0004, שקו האמצעי המייחד ימין ושמאל משמש ג\"כ בזרקא הזה, כי המסך דחירק שבו הוא ג\"כ מכח המלכות דמפתחא, (כנ\"ל לך דף י\"ג ד\"ה ונתבאר) שה\"ס זריקת המלכות לבינה. וז\"ש, \u0003י' כריכא ביה\u0004, שסוד ה \u0003י'\u0004 הנכנסת לאור ונעשה אויר, כרוכה בקו האמצעי. \u0003וקו, ו' דאתפשטא מניה\u0004, הקו ה\"ס \u0003ו'\u0004 דהיינו קו האמצעי, המתפשט מכח \u0003י'\u0004 זו וממעט השמאל, ואח\"כ מיחד ימין ושמאל, (כמ\"ש שם) \u0003ביה תפיס לסמאל\u0004, בה, ב \u0003י'\u0004 הכרוכה על הקו, תופס את סמאל, כי \u0003י'\u0004 זו ה\"ס המוקש שמשימים לס\"א, כנ\"ל במיתת סקילה, שע\"י המוקש הזה תופש אה הס\"א, ואה\"כ מביא עליו ד' מיתות. ועתה מבאר ענין החנק. \u0003וישאוהו במוט בשנים\u0004. שמקרא זה רומז על סמאל, שהיה אחוז בעצת מרגלים, והם נשאו את סמאל, במוט בשנים. שואל, \u0003מאי מוט דההוא רשע\u0004, כלומר, מהו המוט, שאותו רשע סמאל נאחז בו, שעליו כתוב \u0003וישאוהו במוט\u0004. ומשיב, \u0003אדם\u0004 שה\"ס מ\"ה, \u0003דאיהו יוד הא ואו הא\u0004 שהוא בגי' \u0003מ\"ה\u0004, המרמז על המוחין דז\"א, \u0003וד' אתוון הויה\u0004, פשוטה בלי מלוי, הרומזת על המלכות, שהם ביחד \u0003מ\"ט, בחושבן מ\"ט אתוון דאינון בשית תיבין דיחודא עלאה\u0004, שבק\"ש, שהוא יחוד ז\"א, \u0003ובשית תיבין דיחודא תתאה\u0004, שבבשכמל\"ו, שהוא יחוד המלכות, \u0003דאינון ו' ו'\u0004, הרומזות על חג\"ת נה\"י דז\"א, ועל חג\"ת נה\"י דמלכות. \u0003והאי הוא וישאוהו במוט\u0004, שסמאל היה נאחז אז במ\"ט אותיות שביחוד ז\"א ויחוד המלכות. \u0003בשנים, בפרודא מנייהו\u0004, בשנים, פירושו בב' ווין שבז\"א ושבמלכות, שהם היו אז בפרוד מן המוחין האלו, מחמת אחיזת סמאל. וז\"ש, \u0003בלא א' באמצע ו\"ו\u0004, כי ה \u0003א'\u0004 שבאמצע \u0003ואו\u0004 יורה על המוחין ועל היחוד של \u0003ו'\u0004 מלים דק\"ש, עם \u0003ו'\u0004 מלים דבשכמל\"ו, וכיון שסמאל נאחז במוט, שהם המוחין דז\"א ומלכות, ע\"כ היו אלו ב' ווין בפרוד, כי \u0003סמאל ובת זוגיה עולם הנפרדים\u0004, כי הם, בכל מקום אחיזתם, עושים פירוד בין ז\"א ומלכות. ועל זה רומז \u0003בשנים\u0004, שז\"א ומלכות היו שנים בלי יחוד, מחמת אחיזת ס\"א. אבל \u0003ואו\u0004 עם \u0003א'\u0004, יורה על המוחין דז\"א שמקבל מבינה, אשר אז הוא מיחד ימין ושמאל, ועושה יחוד עליון בק\"ש ויחוד תחתון בבשכמל\"ו, כמ\"ש לעיל (ואתחנן אות ס\"ו) ואז הואו, היא חבל לחנוק בו את סמאל. וז\"ש (באות ו') \u0003בחבל דיחנק בה אחידן ה\"א ה\"א, בה' אצבען דיד ימינא ובה' דיד שמאלא.\u0004 כי הואו, מיחדת ב' ההין דהויה, שהן בינה ומלכות שיאירו זו בזו, ע\"י זה שמיחד ב' הידים שהם ימין ושמאל, ואז נעשה ב' יחודין דק\"ש, שבהם נחנק הס\"א. וז\"ש \u0003ו' חבל, י' חניקה דלהון\u0004, שהו' ה\"ס החבל הפועל החניקה ע\"י ב' היחודין, והחניקה עצמה ה\"ס \u0003י'\u0004 הכרוכה על ה \u0003ו'\u0004 דזרקא. כי זולתה לא היו נמשכים המוחין, כנ\"ל."],[9,"","וז\"ש (באות ו') \u0003שמא דהויה מיתה לסמאל ונחש, וחיים לישראל\u0004, דהיינו המוחין הנמשכים בסוד ד' אותיות הויה ובהויה במילוי אלפין הנ\"ל, הוא מיתה לסמאל, כי בזה נפסק כל חיותו. וחיים לישראל. כי החיים של ישראל ממיתים הס\"א. וכן להיפך. \u0003ובג\"ד ראו עתה\u0004 וכו'."]],[[0,"","שֹׁפְטִים וְֹשטְרִים תִּתֶּן לְךְ בְּכָל שְׁעָרֶיךְ אֲשֶׁר ה' אֱלֹהֶיךְ נֹתֵן לְךְ וְגוֹ' [דברים טז] בְּמִצְוָה זוֹ לְמַנּוֹת שׁוֹפְטִים וְשׁוֹטְרִיִם. וְעוֹד, [תהלים עה] כי אלהים שפט. כי י' [מ', ממנּוּ], יו\"ד שחשבונו כ', אחר כאן, כי אלהים שפט, זה ישפיל, ה\"א ה\"א, וזה ירים, זה ו' ו'."],[1,"","מִצְוָה אַחַר זוֹ – לָדוּן בְּסַיִף, לָדוּן בְּחֶנֶק, לָדוּן בְּדִין סְקִילָה, לָדוּן בְּדִין שְׂרֵפָה. לָדוּן בְּסַיִף לְמִי? לְסָמָאֵ\"ל. זֶהוּ שֶׁכָּתוּב [ישעיה לד] כִּי רִוְּתָה בַשָּׁמַיִם חַרְבִּי הִנֵּה עַל אֱדוֹם תֵּרֵד."],[2,"","חֶרֶב שֶׁל הַקָּדוֹשׁ בָּרוּךְ הוּא – י' רֹאשׁ הַחֶרֶב, ו' גּוּף הַחֶרֶב, הֵ\"א הֵ\"א שְׁתֵּי פִיפִיּוֹת שֶׁלָּהּ. צֶדֶק צֶדֶק תִּרְדּף, חוֹתְכִים שְׁנֵי דִינִים, דִּין מִפִּי בֵּית דִּין שֶׁל מַעְלָה וְדִין מִפִּי בֵּית דִּין שֶׁל מַטָּה. וּמִכָּאן נוֹדָע, אֵין אָדָם נוֹקֵף אֶצְבָּעוֹ מִלְּמַטָּה עַד שֶׁנִּתֶּנֶת לוֹ רְשׁוּת מִלְמַעְלָה."],[3,"","נַרְתִּיק שֶׁל הַחֶרֶב – אֲדֹנָ\"י, שָׁם נִמְצָא דִין. בִּקְרִיאַת שְׁמַע – יְהֹוָ\"ה. חֶרֶב שֶׁל הַקָּדוֹשׁ בָּרוּךְ הוּא, עָלֶיהָ נֶאֱמַר [תהלים קמט] רוֹמְמוֹת אֵל בִּגְרוֹנָם וְחֶרֶב פִּיפִיּוֹת בְּיָדָם. בְּצַדִּיק חַי הָעוֹלָמִים, כּוֹלֵל חַ\"י בְּרָכוֹת, שֶׁבּוֹ אֲדנָי שְׂפָתַי תִּפְתָּח וּפִי, בּוֹ נִכְנֶסֶת הַחֶרֶב בְּנַרְתִּיקָהּ, [אסתר ז] וַחֲמַת הַמֶּלֶךְ שָׁכָכָה, וּמִתְחַבְּרִים שְׁנֵי שֵׁמוֹת – יְאֲהֹדוָנָהי."],[4,"","לָדוּן בְּחֶנֶק – זַרְקָא. שָׁם קַו, י' כְּרוּכָה בוֹ, וְקַו, אוֹת ו' שֶׁמִּתְפַּשֶּׁטֶת מִמֶּנָּה. בּוֹ תּוֹפֵס לְסָמָאֵ\"ל, [במדבר יג] וַיִּשָּׂאֻהוּ בַמּוֹט בִּשְׁנָיִם. מַהוּ מוֹט שֶׁל אוֹתוֹ רָשָׁע? אָדָם, שֶׁהוּא יוֹ\"ד הֵ\"א וָא\"ו הֵ\"א, מ\"ה, וְאַרְבַּע אוֹתִיּוֹת יהוה – הֲרֵי אַרְבָּעִים וָתֵשַׁע, כְּחֶשְׁבּוֹן תֵּשַׁע וְאַרְבָּעִים אוֹתִיּוֹת שֶׁהֵן בְּשֵׁשׁ תֵּבוֹת שֶׁל הַיִּחוּד הָעֶלְיוֹן וּבְשֵׁשׁ תֵּבוֹת שֶׁל הַיִּחוּד הַתַּחְתּוֹן, שֶׁהֵן אוֹתִיּוֹת ו' ו'. וְזֶהוּ וַיִּשָּׂאֻהוּ בַמּוֹט בִּשְׁנָיִם, בְּנִפְרָד מֵהֶם, בְּלִי א' בְּאֶמְצַע וָ\"ו, שֶׁאֵין יִחוּד לַצַּד הָאַחֵר, אֶלָּא וַיִּשָּׂאֻהוּ בַמּוֹט בִּשְׁנָיִם, סָמָאֵ\"ל וּבַת זוּגוֹ, עוֹלַם הַנִּפְרָדִים."],[5,"","בַּחֶבֶל שֶׁיֵּחָנֵק בָּהּ אֲחוּזוֹת הֵ\"א הֵ\"א בְּחָמֵשׁ אֶצְבָּעוֹת שֶׁל יַד יָמִין וּבְחָמֵשׁ שֶׁל יַד שְׂמֹאל. ו' – הַחֶבֶל. י' – הַחֲנִיקָה שֶׁלָּהֶם. שֵׁם יְהֹוָ\"ה – מִיתָה לְסָמָאֵ\"ל וְהַנָּחָשׁ, וְחַיִּים לְיִשְׂרָאֵל, וּמִשּׁוּם זֶה [דברים לב] רְאוּ עַתָּה כִּי אֲנִ\"י אֲנִי הוּא וְאֵין אֱלֹהִים עִמָּדִי, אֲנִי אָמִית – לֵאלֹהִים אֲחֵרִים בִּשְׁמִי וּלְכָל שֶׁלֹּא הֶאֱמִינוּ בוֹ, וַאֲחַיֶּה – לְאֵלּוּ שֶׁמַּאֲמִינִים וְשׁוֹמְרִים מִצְווֹת שֶׁלִּי."],[6,"","לָדוּן בִּסְקִילָה – לְסָמָאֵ\"ל, בְּאֶבֶן שֶׁהִיא י' זוֹרֵק לָהּ [צדיק] אֶצְלָהּ בְּחָמֵשׁ אֶצְבָּעוֹת שֶׁהֵם ה', וּבַקָּנֶה שֶׁל הַזְּרוֹעַ שֶׁהוּא ו', וּבַכָּתֵף שֶׁשָּׁם ה'. וְזוֹרֵק אוֹתָהּ אֶל הַמַּחֲשָׁבָה, שֶׁהוּא שֵׁם הַמְפֹרָשׁ יוֹ\"ד הֵ\"א וָא\"ו הֵ\"א."],[7,"","לָדוּן בִּשְׂרֵפָה – לְסָמָאֵ\"ל, עֵצִים לְהַדְלִיק בָּהֶם אֵשׁ. אַשְׁרָיו הַגּוּף שֶׁהוּא עֵץ, וְאֵיבָרִים שֶׁלּוֹ עֵץ, לְהַדְלִיק בָּהֶם אֵשׁ, שֶׁהוּא נֵר מִצְוָה, בְּכָל אֵיבָר, לְהַבְעִיר אֶת סָמָאֵ\"ל בַּשְּׁכִינָה הָעֶלְיוֹנָה בְּעֵץ, שֶׁהוּא תִפְאֶרֶת, וּבְכָל עֵצִים שֶׁאֲחוּזִים בּוֹ. שֶׁבִּזְמַן שֶׁאֵשׁ שֶׁל גָּבוֹהַּ הָיָה יוֹרֵד עַל גַּבֵּי הָעֵצִים שֶׁל הַקָּרְבָּן, [במדבר א] וְהַזָּר הַקָּרֵב יוּמָת, שֶׁנִּשְׂרָף בּוֹ. זֶהוּ שֶׁכָּתוּב [ויקרא ו] וְהָאֵשׁ עַל הַמִּזְבֵּחַ תּוּקַד בּוֹ. אַשְׁרָיו מִי שֶׁאָחוּז בְּאִילַן הַחַיִּים בְּגוּפוֹ, בָּאֵיבָרִים שֶׁלּוֹ, נֵר – כָּל עָנָף וְעָנָף נֵר מִצְוָה בְּמָאתַיִם וְאַרְבָּעִים וּשְׁמוֹנֶה מִצְווֹת שֶׁלּוֹ."],[8,"","כַּאֲשֶׁר אֲחוּזִים בּוֹ שְׁנֵיהֶם, יִתְקַיֵּם [שמות ג] וַיַּרְא וְהִנֵּה הַסְּנֶה בֹּעֵר בָּאֵשׁ וְהַסְּנֶה אֵינֶנּוּ אֻכָּל. וְסָמָאֵ\"ל וְהַנָּחָשׁ וְכָל הַמְמֻנִּים שֶׁלּוֹ, שֶׁהֵם קוֹצִים, נִשְׂרְפוּ. וְהָעֲנָפִים שֶׁל הַסְּנֶה, וְהַפְּרִי שֶׁלּוֹ, וְהֶעָלִים שֶׁלּוֹ, לֹא נִשְׂרְפוּ. זֶה הֶרְאָה לוֹ הַקָּדוֹשׁ בָּרוּךְ הוּא."],[9,"","אָמַר הַמְּנוֹרָה הַקְּדוֹשָׁה, וַדַּאי יִשְׂרָאֵל הֵם עֵצִים יְבֵשִׁים בַּתּוֹרָה, מִשּׁוּם שֶׁאֲחוּזִים בְּאֵשׁ שֶׁל הֶדְיוֹט, אֵינָם כְּמוֹ שֶׁרָאוּי לַעֲשׂוֹת לָהֶם נֵס. מִיָּד שֶׁאַתָּה יוֹרֵד עֲלֵיהֶם בַּתּוֹרָה, בִּגְלָלְךְ יָרַד עֲלֵיהֶם עֵץ הַחַיִּים, וּמִצְוָה שֶׁהִיא נֵר ה', וְאוֹחֶזֶת בָּהֶם וְיִהְיוּ חַיִּים. וְאֻמּוֹת עוֹבְדֵי כוֹכָבִים וּמַזָּלוֹת שֶׁל הָעוֹלָם נִשְׂרָפִים בְּאוֹתוֹ נֵר. וְזֶהוּ שֶׁאָמַר הַנָּבִיא, [ירמיה מו] וְאַתָּה אַל תִּירָא עַבְדִּי יַעֲקֹב וְאַל תֵּחַת יִשְׂרָאֵל כִּי אִתְּךְ אָנִי וְגוֹ'."]]],[["(ארבעים יכנו וגו' ר\"פ ע\"ב) (דברים י״ט:ט״ו) לֹא יָקוּם עֵד אֶחָד בְּאִישׁ לְכָל עָוֹן וְגוֹ'. עַל פִּי שְׁנֵי עֵדִים אוֹ עַל פִּי שְׁלֹשָׁה עֵדִים יָקוּם דָּבָר. פִּקּוּדָא דָּא, לְהָעִיד עֵדוּת בְּבֵּית דִּין, דְּלָא יַפְסִיד חַבְרֵיהּ מָמוֹנָא בְּגִינֵיהּ, אִי אִית לֵיהּ עֵדוּת בַּהֲדֵיהּ. וְלֵית סַהֲדוּתָא פָּחוּת מִתְּרֵין, הֲדָא הוּא דִכְתִיב עַל פִּי שְׁנַיִם עֵדִים וְגוֹ' יָקוּם דָּבָר, לֹא יָקוּם עַל פִּי עֵד אֶחָד. וּבְגִין דָּא אוּקְמוּהָ מָארֵי מָתְנִיתִין, מִי מֵעִיד עַל הָאָדָם, קִירוֹת בֵּיתוֹ. וְלֹא עוֹד אֶלָּא אַנְשֵׁי בֵּיתוֹ מְעִידִין עָלָיו. מַאי קִירוֹת בֵּיתוֹ. אִינּוּן קִירוֹת לִבּוֹ. (ישעיהו ל״ח:ב׳) וַיַּסֵּב חִזְקִיָּהוּ פָּנָיו אֶל הַקִּיר, וְאוֹקְמוּהָ רַבָּנָן, מְלַמֵּד שֶׁהִתְפַּלֵל חִזְקִיָּהוּ מִקִּירוֹת לִבּוֹ.","אַנְשֵׁי בֵּיתוֹ, אִינּוּן רמ\"ח אֵבָרִים דִּילֵיהּ. דְּהָכִי אוּקְמוּהָ מָארֵי מָתְנִיתִין, רָשָׁע עֲוֹנוֹתָיו חֲקוּקִים עַל עַצְמוֹתָיו. וְהָכִי צַדִּיק, זָכִיוֹתָיו חֲקוּקִים לוֹ עַל עַצְמוֹתָיו. וּבְּגִין כָּךְ אָמַר דָּוִד (תהלים לט) כָּל עַצְמוֹתַי תֹּאמַרְנָה. וּבְגִינֵהּ אִתְּמַר, וּמִי מְעִידִין עַל הָאָדָם קוֹרוֹת בֵּיתוֹ. גַּרְמִין בְּנוּיִין עַל מוֹחָא דְּאִיהוּ מַיָּא. וְעָלַיְיהוּ קָא רָמִיז, (תהילים ק״ד:ג׳) הַמְקָרֶה בַמַיִם עֲלִיּוֹתָיו, הַמְקָרֶה לָשׁוֹן קוֹרוֹת.","וַאֲמַאי בְּגַרְמִין יַתִּיר מִבִּשְׂרָא וְגִידִין וּמִשְׁכָא. בְּגִין דְּגַרְמִין אִינּוּן חִוָּורִין, וּכְתִיבָא אוּכָּמָא, לָא אִשְׁתְּמוֹדְעָא אֶלָּא מִגּוֹ חִוָּורוּ. כְּגַוְונָא דְּאוֹרַיְיתָא, דְּאִיהִי חִוָּורוּ מִלְּגָאו, אוּכָם מִלְּבַר. אוּכָם וְחִוָּור, חֹשֶׁךְ וְאוֹר. וְאִית חֹשֶׁךְ תְּכֵלֶת, וְאִתְּמַר בֵּיהּ (תהילים קל״ט:י״ב) גַּם חֹשֶׁךְ לֹא יַחֲשִׁיךְ מִמֶּךָּ. וּתְכֵלֶת אוּכָם, אִיהוּ נוּקְבָּא לְגַבֵּי חִוָּורוּ.","וְלֹא עוֹד, אֶלָּא דְּגוּפָא עַל גַּרְמִין עָתִיד לְמֵיקָם. וּבְגִין דָּא זַכְווֹי וְחוֹבוֹי חָקוּקִין עַל גַּרְמִין דִּילֵיהּ, וְאִם יִזְכֶּה יְקוּם גּוּפָא עַל גַּרְמִין דִּילֵיהּ. וְאִי לָאו, לָא יְקוּם, וְלָא יְהֵא לֵיהּ תְּחִיַּית הַמֵּתִים. וְלָא עוֹד, אֶלָּא תְּרֵין סָהֲדִין אִינּוּן עַל בַּר נָשׁ, עַיִן רוֹאָה וְאוֹזֶן שׁוֹמַעַת, וּבֵּית דִּין סוֹפֵר, וְדָן חוֹבוֹי. וְלֹא עוֹד, אֶלָּא שִׁמְשָׁא וְסִיהֲרָא סָהֲדִין עַל בַּר נָשׁ, כְּמָה דְּאוֹקְמוּהָ (תהילים פ״א:ד׳) תִּקְעוּ בַחֹדֶשׁ שׁוֹפָר בַּכֶּסֶה לְיוֹם חַגֵּנוּ. מַאי בַּכֶּסֶה. בְּיוֹמָא דְּסִיהֲרָא מִתְכַּסָה. וַאֲמַאי מִתְכַּסֵּת. בְּגִין דְּכַד מָטֵי רֹאשׁ הַשָּׁנָה, יֵיתֵי סָמָאֵל לְמִתְבַּע דִּינָא לִבְנוֹי קַמֵּי קוּדְשָׁא בְּרִיךְ הוּא, וְהוּא יֵימָא לֵיהּ דְּיֵיתֵי סָהֲדִין. וְהוּא יֵיתֵי לְשִׁמְּשָׁא עִמֵּיהּ. אָזַל לְמַיְיתֵי סִיהֲרָא, וְהִיא מִתְכַּסָא. בְּאָן אֲתָר מִתְכַּסֵּת. אֶלָּא סְלִיקַת, לְהַהוּא אֲתָר, דְּאִתְּמַר בֵּיהּ בַּמְכוּסֶּה מִמָּךְ אַל תַּחְקוֹר, לְפַיְּיסָא לֵיהּ עַל בְּנָהָא.","וְהַאי הוּא דְּאָמַר קְרָא, תִּקְעוּ בַחֹדֶשׁ שׁוֹפָר בַּכֶּסֶה לְיוֹם חַגֵּנוּ. לַאֲתָר דְּבֵיהּ סְלִיקַת שְׁכִינְתָּא, דְּאִתְּמַר בֵּיהּ וּבַמְכוּסֶּה מִמָּךְ אַל תַּחְקוֹר. וְחוֹבִין בְּאִתְכַּסְיָיא, תַּמָּן צָרִיךְ לְמֵידָן בֵּינוֹ לְבֵין קוֹנוֹ. וְחוֹבִין דְּאִתְגַּלְיָיא דְּעָבַד לוֹן, אִתְּמַר (משלי כ״ח:י״ג) מְכַסֶּה פְּשָׁעָיו לֹא יַצְלִיחַ. דִּשְׁכִינְתָּא מִסִּטְרָא דְּכֶתֶר אִיהִי עָלְמָא דְּאִתְכַּסְּיָא, וְאוֹקְמוּהָ מָארֵי מָתְנִיתִין, דְּצָרִיךְ בַּר נָשׁ לְחַבְּרָא לָהּ לְהַהוּא אַתְרָא. בְּהַהוּא זִמְנָא מָטֵי זִמְנָא דְּרַחֲמֵי, וְאַעְבַּר דִּינָא. וּבְגִין דָּא לְחַבְרֵיהּ אָמַר לְזַכָּאָה לֵיהּ בְּעֵדוּתֵיהּ, אֲבָל לְרָשָׁע אֵין מְזַכִּין לוֹ.","וְעוֹד, קוּדְשָׁא בְּרִיךְ הוּא וּשְׁכִינְתֵּיהּ סָהֲדִין עַל בַּר נָשׁ, הֲדָא הוּא דִכְתִיב, (דברים א) הֲעִדוֹתִי בָכֶם הַיּוֹם אֶת הַשָּׁמַיִם וְאֶת הָאָרֶץ. אֶת הַשָּׁמַיִם, הַהוּא דְּאִתְּמַר בֵּיהּ (מלכים א ח׳:ל״ב) וְאַתָּה תִּשְׁמַע הַשָּׁמַיִם. וְאֶת הָאָרֶץ, הַהוּא דְּאִתְּמַר בָּהּ (ישעיהו ס״ו:א׳) וְהָאָרֶץ הֲדוֹם רַגְלָי. וְעוֹד, תְּרֵין סָהֲדִין: עַמּוּדָא דְּאֶמְצָעִיתָא, וְצַדִּיק. וְאִינּוּן ע\"ד, מִן שְׁמַ\"ע אֶחָד. עֵד, מִן בָּרוּךְ שֵׁם כְּבוֹד מַלְכוּתוֹ לְעוֹלָם וָעֶד.","עַל פִּי שְׁנַיִם עֵדִים אוֹ שְׁלֹשָׁה עֵדִים יוּמַת הַמֵּת, דָּא סָמָאֵל, מֵת מֵעִקָרוֹ (במדבר י״ג:כ״ג) וַיִּשָּׂאוּהוּ בַמּוֹט בִּשְׁנָיִם. לֹא יוּמַת עַל פִּי עֵד אֶחָד, דְּלָא יְהֵא לֵיהּ חוּלָקָא בְּאֵל אֶחָד.","כִּי יָקוּם עֵד חָמָס בְּאִישׁ וְגוֹ' וְדָרְשׁוּ הַשּׁוֹפְטִים הֵיטֵב וְגוֹ', וַעֲשִׂיתֶם לוֹ כַּאֲשֶׁר זָמַם וְגוֹ'. פִּקּוּדָא דָּא לִדְרוֹשׁ וְלַחֲקוֹר הָעֵדִים בְּז' חֲקִירוֹת, קוֹדֶם דְּיָדִין לֵיהּ בְּעוֹנְשָׁא דְּמוֹתָא, בְּשֶׁבַע חֲקִירוֹת, שֶׁבַע לָקֳבֵל (זכריה ד׳:י׳) שִׁבְעָה אֵלֶּה עֵינֵי יְיָ' הֵמָּה מְשׁוֹטְטִים בְּכָל הָאָרֶץ. בְּהוֹן (ויקרא כ״ו:כ״ח) וְיִסַּרְתִּי אֶתְכֶם אַף אָנִי שֶׁבַע.","פִּקּוּדָא בָּתַר דָּא, לַעֲשׂוֹת לְעֵד זוֹמֵם כַּאֲשֶׁר זָמַם לַעֲשׂוֹת לְאָחִיו. תְּרֵין סַהֲדֵי שִׁקְרָא דְּאִינּוּן סָמָאֵל וְנַחַשׁ, אִי יֵיתוּן לְאַסְהֲדָא סָהֲדוּתָא דְּשֶׁקֶר עַל יִשְׂרָאֵל, דְּטָעוּ בֵּין ו' לְז' דְּאִינּוּן אַתְוָון זוּ. וְהַאי אִיהוּ (ישעיהו מ״ג:כ״א) עַם זוּ יָצַרְתִּי לִי תְּהִלָּתִי יְסַפֵּרוּ.","וְלָא יִתְיַיחֵד ו' עִם ז', אֶלָּא בִּשְׂרֵפַת חָמֵץ, דְּבֵין ו' לְז'. וְאַף עַל גַּב דְּמִדְּאוֹרַיְיתָא אִיהוּ עַד סוֹף שִׁית, גָּזְרוּ רַבָּנָן, אוֹכְלִין כָּל אַרְבַּע, וְתוֹלִין כָּל חָמֵשׁ, וְשׂוֹרְפִין בִּתְחִלַּת שֵׁשׁ. וְאוֹלְפִי מָארֵי מַתְנִיתִין מִסַהֲדוּתָא דְּשַׁעְתֵּי דְּחָמֵץ, לְסַהֲדוּתָא דִּבְדִיקוֹת דְּסָהֲדֵי, דְּהַהוּא דְּהָרַג אֶת הַנֶּפֶשׁ. וְכֹלָּא מְפֹרָשׁ בְּמַתְנִיתִין. וִיקֻיָים בְּהוֹן, אֲרֵי בְּפִתְגָּמָא דְּחָשִׁיבוּ מִצְרָאֵי לְמֵידָן וְכוּ'. וְהַאי אִיהוּ וַעֲשִׂיתֶם לוֹ כַּאֲשֶׁר זָמַם."],[[0,"לא יקום עד וגו':","לא יקום עד אחד וגו': מצוה זו היא להעיד עדות בב\"ד, שלא יפסיד חברו כסף בשביל שאינו מעיד, אם הוא יודע עדות בשבילו. ואין עדות פחות משנים, ז\"ש על פי שנים עדים וגו' יקום דבר, לא יקום על פי עד אחד. ומשום זה העמידו בעלי המשנה מי מעיד על האדם, קירות ביתו. ולא עוד אלא אנשי ביתו מעידים עליו. מהו קירות ביתו. אלו הם קירות לבו. שכתוב, ויסב חזקיהו פניו אל \u0003הקיר\u0004, והעמידו בעלי המשנה, מלמד שחזקיהו התפלל \u0003מקירות\u0004 לבו."],[1,"אנשי ביתו:","אלו הם רמ\"ח אברים שלו. כי הגוף מכונה בית. שכך העמידו בעלי המשנה, רשע עונותיו חקוקים על עצמותיו. וכך צדיק, זכיותיו חקוקות על עצמותיו. ומשום זה אמר דוד, כל עצמותי תאמרנה. ובשביל זה למדנו ומי מעידים על האדם קורות ביתו. קורות ביתו הן העצמות הגלגלת הבנוים על המוח שהוא מים. ועליהם רומז, המקרה במים עליותיו. המקרה, הוא לשון קורות."],[2,"ואמאי בגרמין יתיר וכו':","ולמה העונות חקוקים בעצמות יותר מבבשר גידים ועור. הוא משום שהעצמות הם לבנים, וכתב שחור אינו ניכר אלא מתוך לבן. כמו התורה, שהיא לבן מבפנים, דהיינו הגויל, ושחור מבחוץ, דהיינו הדיו. שחור ולבן הם חושך ואור. ויש חשך שהוא תכלת, שהיא המלכות, שנאמר בה גם חשך לא יחשיך ממך. ותכלת הוא שחור, והיא נקבה אל הלבן, שהוא ז\"א. כי המלכות אין לה אור מעצמה. אלא מה שנותן בה ז\"א. ולא עוד אלא שהגוף עתיד לקום על עצמותיו, ומשום זה הזכיות והחובות חקוקים על עצמותיו ואם יזכה יקום הגוף על העצמות שלו. ואם לא יזכה, לא יקום ולא יהיה לו תחיית המתים."],[3,"ולא עוד אלא וכו':","ולא עוד אלא ב' עדים הם על האדם עין רואה, ואזן שומעת. והבית דין, סופר ודן עונותיו. ולא עוד, אלא השמש והלבנה מעידים על האדם. כמו שהעמדנו, תקעו בחדש שופר בכסה ליום חגנו. מהו בכסה. הוא ביום שהלבנה שהיא המלכות, מתכסה בו. ולמה היא מתכסה. הוא משום כשמגיע ראש השנה, יבא סמאל לבקש דין על בניה, דהיינו ישראל שהם בני המלכות, לפני הקב\"ה. והוא יאמר לו שיביא עדים. והוא מביא עמו את השמש. הלך להביא את הלבנה, והיא מתכסה. באיזה מקום היא מתכסה. ומשיב, אלא שהיא עולה לאותו מקום שנאמר בו, \u0003במכוסה\u0004 ממך אל תחקור, כדי לפייס את הקב\"ה על בניה."],[4,"והאי הוא דאמר","וכו': וזה הוא שאמר הכתוב, תקעו בחדש שופר בכסה ליום חגנו. היינו למקום שבו עלתה השכינה, שנאמר בו \u0003ובמכוסה\u0004 ממך אל תחקור. והעונות שהם \u0003בסתר\u0004, צריכים להיות נדונים שמה בינו לבין קונו. והעונות שחטא בגלוי, נאמר, מכסה פשעיו לא יצליח. והשכינה מצד הכתר, היא עולם הנסתר. והעמידו בעלי המשנה שאדם צריך לחבר עונותיו למקום ההוא, שהוא כתר, בזמן ההוא מגיע זמן הרחמים והדין עובר. ומשום זה אמר לחבר עונותיו בכתר, לזכותו מן העדות של המלכות. אבל לרשע אין מזכין לו."],[4,"","פירוש. כי ברה\"ש חוזר העולם לקדמותו, והמלכות חוזרת למצב הא' שבו היתה ביום ד' דמעשה בראשית, דהיינו בבחינת ב' מאורות הגדולים, שז\"א ונוקבא הלבישו את הבינה, ז\"א הקו ימין דבינה, והמלכות קו השמאל. ונודע שהארת השמאל בלי ימין הוא חשך (כנ\"ל ב\"א דף מ\"ז אות לד ד\"ה נפק) וכן ימין בלי שמאל הוא ו\"ק בלי מוחין. ולפיכך היה אז ז\"א בדורמיטא, דהיינו כמו ישן בלי מוחין. והנוקבא היתה בחשך. ואז בא סמאל לתבוע דין, ונאמר לו להביא ב' עדים. דהיינו ז\"א ומלכות, שהשמים שהוא ז\"א לא יתן מטר, דהיינו שלא ישפיע אל המלכות. והארץ, שהיא המלכות לא תתן את יבולה לתחתונים. אמנם סמאל לא הביא עמו אלא עד אחד שהוא השמים דהיינו ז\"א שהיה בדורמיטא ולא השפיע למלכות. וכיון שהלך להביא את המלכות, שלא תתן יבולה לתחתונים, אז נתכסתה המלכות, דהיינו שנתמעטה מכל ט\"ס תחתוניות שבה, ונשארה בנקודת כתר שבה. שמיעוט הזה נעשה על ידי תקיעת שופר, שע\"י הקול היוצא משופר מעוררים כח המסך דחירק בז\"א שה\"ס קו האמצעי, וע\"י מסך דחירק הוא ממעט קו השמאל דבינה, ומיחד שם ימין ושמאל דבינה זה בזה, ונתעוררו הרחמים בעולם מכח יחוד הזה דימין ושמאל (כנ\"ל ויקרא דף ק' ד\"ה אות ש\"ד פירוש. ע\"ש). וכיון שנתמעט קו השמאל דבינה, נסתלקו אז כל ט\"ס תחתונות מן המלכות, שכל בנינה היה אז מקו השמאל הזה, ונשארה בנקודת הכתר. וז\"ס \u0003תקעו בחדש שופר,\u0004 שעי\"ז \u0003בכסה\u0004 ליום חגנו. שהלבנה, שה\"ס המלכות מתכסה בסוד נקודת הכתר שבה. שעי\"ז נעלם הדין ומתגלה הרחמים בדין."],[4,"","וז\"ש (באות י\"ד) \u0003ואמאי מתכסת\u0004 וכו' \u0003והוא ייתי לשמשא עמיה,\u0004 דהיינו מה שז\"א אין לו מוחין ואינו משפיע. \u0003אזל למייתי סיהרא,\u0004 וכו' דהיינו להראות על החשך שבה, \u0003סליקת לההוא אתר\u0004 וכו' \u0003במכוסה ממך אל תחקור,\u0004 דהיינו שנתמעטה מכל הספירות שבה ולא נשאר בה אלא הכתר, שעליו נאמר, במכוסה ממך אל תחקור, ואז יצא הרחמים בעולם כנ\"ל. וז\"ש \u0003וחובין באתכסיא תמן צריך למידן בינו לבין קונו,\u0004 כי לאחר שהקו שמאל נתמעט ויצאה מדת הרחמים כבר אין לסמאל אחיזה בהמלכות, ודינים של אדם הם בינו לבין קונו, בלי קטרוגו של סמאל, וע\"כ ה' מרחם עליו. אבל בעוד ששלט קו שמאל, \u0003וחובין באתגליא\u0004 וכו' שעונותיו של אדם היו נאחזים בעלמא דאתגליא, שהוא המלכות. אתמר מכסה פשעיו לא יצליח, שלא יוכל לכסות הפשעים באפן שסמאל לא יהיה נאחז במלכות. \u0003דשכינתא מסטרא דכתר איהי עלמא דאתכסיא,\u0004 שבעת שהשכינה היא בבחינת כתר שבה, אז היא עלמא דאתכסיא, כי הכתר נקרא במכוסה ממך. ואין אחיזה לסמאל. וז\"ש \u0003דצריך ב\"נ לחברא להו לההוא אתרא, בההוא זמנא מטי זמנא דרחמי\u0004 דהיינו כנ\"ל, שאז נעשה יחוד ימין ושמאל ע\"י קו אמצעי והרחמים מתגלים. \u0003ובג\"ד, לחברא אמר לזכאה ליה בעדותיה\u0004 ומשום זה, הרשע שהוא \u0003מכסה פשעיו,\u0004 דהיינו שהרשע אומר לחבר עונותיו לבחינת הכתר לזכותו מן העדות שלה, דהיינו שלא תוכל להעיד ששם המלכות במכוסה, \u0003אבל לרשע אין מזכין לו.\u0004 וע\"כ נאמר \u0003לא יצליח.\u0004 אבל לאחר שז\"א ממעט השמאל, ומסבה זו עלתה המלכות עד הכתר שנשאר בה, מתגלה מדת הרחמים."],[5,"ועוד קב\"ה ושכינתיה","וכו': ועוד. הקב\"ה ושכינתו מעידים על האדם, תמיד. ולא ברה\"ש לבד כנ\"ל, ז\"ש, העידותי בכם היום את השמים ואת הארץ. \u0003את השמים\u0004 הוא אותו שנאמר בו, ואתה תשמע השמים, שהוא ז\"א. ואת הארץ, הוא אותו שנאמר בו, והארץ הדום רגלי, שהיא המלכות. ועוד. ב' עדות, הם, עמוד האמצעי, שהוא ז\"א, וצדיק, שהוא יסוד. והם \u0003ע\"ד\u0004 מן שמ \u0003ע\u0004 אח \u0003ד\u0004, דהיינו \u0003ע'\u0004 מן שמע, ו \u0003ד'\u0004 מן אחד. וזהו \u0003עד\u0004 מבחינת ז\"א. ועוד \u0003ע\"ד\u0004 מן ברוך שם כבוד מלכותו לעולם ו \u0003עד\u0004, דהיינו \u0003עד\u0004 מהמלה ועד. שהוא \u0003עד\u0004 מבחינת יסוד דז\"א הכלול במלכות."],[6,"על פי שנים","וגו': על פי שנים עדים או שלשה עדים יומת המת. זהו סמאל, שהוא מת מעקרו. וישאהו במוט בשנים. לא יומת על פי עד אחד. היינו שלא יהיה לו חלק באל אחד."],[6,"","פירוש. כי נתבאר שבראש השנה, נמצאת המלכות בבחינת שמאל בלי ימין, ואז נאחז בה סמאל, עד תקיעת שופר, שה\"ס ז\"א הממעט את הג\"ר דקו שמאל למעלה בבינה, ע\"י הדינים דמסך דחירק, שעל ידו נתמעטה המלכות עד לנקודת הכתר, ואז נפרד סמאל מן המלכות. ויש כאן ב' עדים להרחקת סמאל מן קו שמאל שבמלכות. א', החשך שבה, כי בעת שנתדבקה בשמאל בלי ימין נקפאו אורותיה והיתה לחשך, ועכ\"ז לא נפרד ממנה סמאל והיה יונק ממנה, ולא יכלה להתחבר עם ז\"א בגללו. וז\"ס, \u0003לא יומת על פי עד אחד.\u0004 אלא אח\"כ שע\"י תקיעת שופר שנתעוררו בז\"א הדינין דמסך דחירק, ומיעט הג\"ר בשמאל עם הדינים ההם, וט\"ת דמלכות נסתלקו ונשארה בכתר, אז נפרד סמאל מן המלכות, ויכלה להבנות מחדש ולהתחבר עם ז\"א ולהזדווג עמו פב\"פ. כי עתה שנתוסף הדין דמסך דחירק על הדין דחשך, \u0003אז על פי שנים עדים יקום דבר,\u0004 וסמאל נפרד מן המלכות."],[6,"","וז\"ש, \u0003על פי שנים עדים או שלשה עדים יומת המת. דא סמאל,\u0004 כי היה צריך לומר, יומת החי, ולמה אמר, המת, אלא לרמוז על סמאל שהוא \u0003מת מעקרו.\u0004 ואי אפשר להמיתו בעד אחד דהיינו בדין דחשך, אלא בב' עדים שהם הדין דחושך והדין דמסך דחירק. וזסו\"ה \u0003וישאוהו במוט בשנים,\u0004 דהיינו בב' עדים. \u0003לא יומת על פי עד אחד,\u0004 שהוא הדין דחשך בלבד, והוא מטעם, \u0003דלא יהא ליה חולקא באל אחד.\u0004 כי הדינים דחשך שבמלכות הם קדושים מאד, וה\"ס \u0003ד'\u0004 דאחד, והם נחוצים לסוד היחוד של \u0003א\"ח\u0004 דאחד, עם \u0003ד'\u0004 דאחד. וע\"כ אין מורידים אותם לבחינת מלחמה עם סמאל, אלא שמחכים לעד השני שהוא הדין דמסך דחירק. ומה שאומר הכתוב, \u0003או שלשה עדים.\u0004 הוא משום שבמסך דחירק יש ב' מיני דינים דמנעולא ודמפתחא (עי' לך לך י\"ג אות כ\"ב ד\"ה ונתבאר) ולפיכך הם שלשה דינים שהם חשך, ומנעולא, ומפתחא. ועקרם מספיק בשני עדים, שהם, חשך ומפתחא. אלא תחילה צריך לצאת המנעולא (כמ\"ש שם) ואח\"כ נגנזה. ולפיכך אנו חושבים רק ב' עדים. אע\"פ שע\"פ סדר הפעולות יצאו ג' עדים. וע\"כ אוה\"כ ע\"פ שנים עדים או שלשה וגו'. דהיינו שרמז, שמספיק שנים, אבל יש ג' עדים, שלפני עדותם אינו מתבטל מן המלכות."],[7,"כי יקום עד","וגו' \u0003כאשר זמם\u0004 וגו': מצוה זו היא לדרוש ולחקור העדים בשבע חקירות, מקודם שדנים אותו בעונש מות. בשבע חקירות, הם שבע כנגד שבעה אלה עיני ה' המה משוטטים בכל הארץ. שה\"ס חג\"ת נהי\"מ, בהם נאמר, ויסרתי אתכם אף אני שבע וגו'."],[8,"פקודא בתר דא וכו':","מצוה שלאחר זו, היא, לעשות לעד זומם כאשר זמם לעשות לאחיו. ב' עדי שקר, שהם סמאל ונחש, אם יבואו להעיד עדות שקר על ישראל, שטעו בין \u0003ו'\u0004 ל \u0003ז'\u0004, דהיינו בין ז\"א, שהוא חג\"ת נה\"י, למלכות שהיא \u0003ז'\u0004, דהיינו שחטאו והרחיקו בחטאם את ה \u0003ו'\u0004 שהיא ז\"א, מן ה \u0003ז'\u0004, שהיא מלכות. שהם אותיות \u0003זו\u0004. וזהו, עם \u0003זו\u0004 יצרתי לי תהלתי יספרו. דהיינו, שרומז על העם, שמיחד ה \u0003ז'\u0004 עם ה \u0003ו'\u0004."],[9,"ולא יתייחד ו' וכו':","ולא תתיחד ה \u0003ו'\u0004 עם ה \u0003ז'\u0004, אלא בשריפת חמץ, דהיינו לשרוף הקליפות הנאחזות בין \u0003ו'\u0004 ל \u0003ז'\u0004, דהיינו בין ז\"א למלכות. ואע\"פ שמדאורייתא מותר לאכול עד סוף שש, גזרו חכמים אוכלים כל ארבע ותולין כל חמש ושורפין בתחלת שש. ולמדו חכמי המשנה מן העדות של שעות החמץ, ששורפים מדאורייתא לאחר שש דהיינו בשעה \u0003שבע\u0004, אל העדות של בדיקות העדות שעל אותו שהרג את הנפש, שצריכים ג\"כ \u0003שבע\u0004 חקירות כנ\"ל. והכל מפורש במשנה. ויקוים בהם, בסמאל ונחש, כי בדבר אשר זדו עליהם וגו'. שפירושו, בדבר שחשבו המצרים לדון את ישראל בו נדונו הם. וזהו, ועשיתם לו כאשר זמם."]],[[0,"","לֹא יָקוּם עֵד אֶחָד בְּאִישׁ לְכָל עָוֹן וְגוֹ', עַל פִּי שְׁנֵי עֵדִים אוֹ עַל פִּי שְׁלֹשָׁה עֵדִים יָקוּם דָּבָר [דברים יט]. מִצְוָה זוֹ לְהָעִיד עֵדוּת בְּבֵית דִּין, שֶׁלֹּא יַפְסִיד חֲבֵרוֹ מָמוֹן בִּגְלָלוֹ אִם יֵשׁ לוֹ עֵדוּת עִמּוֹ. וְאֵין עֵדוּת פָּחוֹת מִשְּׁנַיִם, זֶהוּ שֶׁכָּתוּב עַל פִּי שְׁנַיִם [שני] עֵדִים וְגוֹ' יָקוּם דָּבָר, לֹא יָקוּם עַל פִּי עֵד אֶחָד. וּמִשּׁוּם זֶה בֵּאֲרוּהוּ בַּעֲלֵי הַמִּשְׁנָה, מִי מֵעִיד עַל הָאָדָם? קִירוֹת בֵּיתוֹ. וְלֹא עוֹד, אֶלָּא אַנְשֵׁי בֵיתוֹ מְעִידִין עָלָיו. מָהֵם קִירוֹת בֵּיתוֹ? אֵלּוּ קִירוֹת לִבּוֹ. [ישעיה לח] וַיַּסֵּב חִזְקִיָּהוּ פָנָיו אֶל הַקִּיר. וּבֵאֲרוּהוּ רַבּוֹתֵינוּ, מְלַמֵּד שֶׁהִתְפַּלֵּל חִזְקִיָּהוּ מִקִּירוֹת לִבּוֹ."],[1,"","אַנְשֵׁי בֵיתוֹ, אֵלּוּ מָאתַיִם אַרְבָּעִים וּשְׁמוֹנָה אֵיבָרִים שֶׁלּוֹ. שֶׁכָּךְ בֵּאֲרוּ בַּעֲלֵי הַמִּשְׁנָה, רָשָׁע, עֲוֹנוֹתָיו חֲקוּקִים עַל עַצְמוֹתָיו. וְכָךְ צַדִּיק, זְכֻיּוֹתָיו חֲקוּקִים לוֹ עַל עַצְמוֹתָיו. וּמִשּׁוּם זֶה אָמַר דָּוִד, [תהלים לה] כָּל עַצְמֹתַי תֹּאמַרְנָה. וּבִגְלָלוֹ נֶאֱמַר, וּמִי מְעִידִין עַל הָאָדָם? קוֹרוֹת בֵּיתוֹ. עֲצָמוֹת בְּנוּיוֹת עַל הַמֹּחַ, שֶׁהוּא מַיִם. וַעֲלֵיהֶם הוּא רוֹמֵז, [תהלים קד] הַמְקָרֶה בַמַּיִם עֲלִיּוֹתָיו. הַמְקָרֶה, לְשׁוֹן קוֹרוֹת."],[2,"","וּמַדּוּעַ בָּעֲצָמוֹת יוֹתֵר מִבָּשָׂר וְגִידִים וְעוֹר? מִשּׁוּם שֶׁעֲצָמוֹת הֵן לְבָנוֹת, וּכְתִיבָה שְׁחֹרָה לֹא נוֹדַעַת אֶלָּא מִתּוֹךְ לֹבֶן, כְּדֻגְמַת הַתּוֹרָה, שֶׁהִיא לְבָנָה מִבִּפְנִים וּשְׁחֹרָה מִבַּחוּץ. שָׁחֹר וְלָבָן, חֹשֶׁךְ וְאוֹר. וְיֵשׁ חֹשֶׁךְ תְּכֵלֶת, וְנֶאֱמַר בּוֹ [תהלים קלט] גַּם חֹשֶׁךְ לֹא יַחְשִׁיךְ מִמֶּךָּ. וּתְכֵלֶת שָׁחֹר הִיא נְקֵבָה לְגַבֵּי הַלֹּבֶן."],[3,"","וְלֹא עוֹד, אֶלָּא שֶׁהַגּוּף עַל הָעֲצָמוֹת עָתִיד לַעֲמֹד, וּמִשּׁוּם זֶה זְכֻיּוֹתָיו וְחוֹבוֹתָיו חֲקוּקוֹת עַל הָעֲצָמוֹת שֶׁלּוֹ, וְאִם יִזְכֶּה, יָקוּם הַגּוּף עַל הָעֲצָמוֹת שֶׁלּוֹ. וְאִם לֹא, לֹא יָקוּם וְלֹא יִהְיֶה לוֹ תְּחִיַּת הַמֵּתִים. וְלֹא עוֹד, אֶלָּא שְׁנֵי עֵדִים הֵם עַל הָאָדָם – עַיִן רוֹאָה וְאֹזֶן שׁוֹמַעַת, וּבֵית דִּין סוֹפֵר וְדָן חוֹבוֹתָיו. וְלֹא עוֹד, אֶלָּא שֶׁמֶשׁ וְיָרֵחַ מְעִידִים עַל הָאָדָם, כְּמוֹ שֶׁבֵּאֲרוּהוּ [תהלים פא] תִּקְעוּ בַחֹדֶשׁ שׁוֹפָר בַּכֶּסֶה לְיוֹם חַגֵּנוּ. מַהוּ בַכֶּסֶה? בַּיּוֹם שֶׁהַלְּבָנָה מִתְכַּסָּה. וּמַדּוּעַ מִתְכַּסֵּית? מִשּׁוּם שֶׁכַּאֲשֶׁר מַגִּיעַ רֹאשׁ הַשָּׁנָה, מַגִּיעַ סָמָאֵ\"ל לִתְבֹּעַ דִּין לְבָנָיו לִפְנֵי הַקָּדוֹשׁ בָּרוּךְ הוּא, וְהוּא אוֹמֵר לוֹ שֶׁיָּבִיא עֵדִים. וְהוּא מֵבִיא לַשֶּׁמֶשׁ עִמּוֹ. הוֹלֵךְ לְהָבִיא הַלְּבָנָה, וְהִיא מִתְכַּסָּה. בְּאֵיזֶה מָקוֹם מִתְכַּסֵּית? אֶלָּא עוֹלָה לַמָּקוֹם הַהוּא שֶׁנֶּאֱמַר בּוֹ בַּמְכֻסֶּה מִמָּךְ אַל תַּחְקֹר, לְפַיֵּס לוֹ עַל בָּנֶיהָ."],[4,"","וְזְהִוּ שֶׁאָמַר הַפָּסוּק, תִּקְעוּ בַחֹדֶשׁ שׁוֹפָר בַּכֶּסֶה לְיוֹם חַגֵּנוּ. לַמָּקוֹם שֶׁבּוֹ עוֹלָה הַשְּׁכִינָה, שֶׁנֶּאֱמַר בּוֹ וּבַמְכֻסֶּה מִמָּךְ אַל תַּחְקֹר. וַחֲטָאִים בְּכִסּוּי, שָׁם צָרִיךְ לָדוּן בֵּינוֹ לְבֵין קוֹנוֹ. וַעֲבֵרוֹת בְּגָלוּי שֶׁעָשָׂה אוֹתָם, נֶאֱמַר [משלי כח] מְכַסֶּה פְשָׁעָיו לֹא יַצְלִיחַ. שֶׁהַשְּׁכִינָה מִצַּד הַכֶּתֶר הִיא עוֹלָם הַנֶּעְלָם, וּבֵאֲרוּהָ בַּעֲלֵי הַמִּשְׁנָה שֶׁצָּרִיךְ אָדָם לְחַבֵּר אוֹתָהּ לַמָּקוֹם הַהוּא. בַּזְּמַן הַהוּא מַגִּיעַ זְמַן הָרַחֲמִים וְעוֹבֵר הַדִּין. וּמִשּׁוּם זֶה לַחֲבֵרוֹ אָמַר לְזַכּוֹת אוֹתוֹ בְּעֵדוּתוֹ, אֲבָל לְרָשָׁע אֵין מְזַכִּין לוֹ."],[5,"","וְעוֹד, הַקָּדוֹשׁ בָּרוּךְ הוּא וּשְׁכִינָתוֹ עֵדִים עַל הָאָדָם, זֶהוּ שֶׁכָּתוּב [דברים ל] הַעִידתִי בָכֶם הַיּוֹם אֶת הַשָּׁמַיִם וְאֶת הָאָרֶץ. אֶת הַשָּׁמַיִם – אוֹתוֹ שֶׁנֶּאֱמַר בּוֹ [מלכים א ח] וְאַתָּה תִּשְׁמַע הַשָּׁמַיִם. וְאֶת הָאָרֶץ – אוֹתוֹ שֶׁנֶּאֱמַר בּוֹ [ישעיה סו] וְהָאָרֶץ הֲדם רַגְלָי. וְעוֹד, שְׁנֵי עֵדִים – הָעַמּוּד הָאֶמְצָעִי וְצַדִּיק. וְהֵם אוֹתִיּוֹת ע\"ד מִשְּׁמַע אֶחָד. עֵ\"ד – מִבָּרוּךְ שֵׁם כְּבוֹד מַלְכוּתוֹ לְעוֹלָם וָעֶד."],[6,"","עֵל פִּי שְׁנַיִם עֵדִים אוֹ שְׁלֹשָׁה עֵדִים יוּמַת הַמֵּת. זֶה סָמָאֵ\"ל, מֵת מֵעִקָּרוֹ, [במדבר יג] וַיִּשָּׂאֻהוּ בַמּוֹט בִּשְׁנָיִם. לֹא יוּמַת עַל פִּי עֵד אֶחָד, שֶׁלֹּא יִהְיֶה לוֹ חֵלֶק בְּאֵל אֶחָד."],[7,"","כִּי יָקוּם עֵד חָמָס בְּאִישׁ וְגוֹ' וְדָרְשׁוּ הַשּּׁפְטִים הֵיטֵב וְגוֹ', וַעֲשִׂיתֶם לוֹ כַּאֲשֶׁר זָמַם וְגוֹ'. מִצְוָה זוֹ לִדְרֹשׁ וְלַחְקֹר הָעֵדִים בְּשֶׁבַע חֲקִירוֹת קֹדֶם שֶׁיָּדוּן לוֹ בְּעֹנֶשׁ מִיתָה. בְּשֶׁבַע חֲקִירוֹת, שֶׁבַע כְּנֶגֶד [זכריה ד] שִׁבְעָה אֵלֶּה עֵינֵי ה' הֵמָּה מְשׁוֹטְטִים בְּכָל הָאָרֶץ. בָּהֶם [ויקרא כו] וְיִסַּרְתִּי אֶתְכֶם אַף אָנִי שֶׁבַע."],[8,"","מִצְוָה אַחַר זוֹ – לַעֲשׂוֹת לְעֵד זוֹמֵם כַּאֲשֶׁר זָמַם לַעֲשׂוֹת לְאָחִיו. שְׁנֵי עֵדֵי שֶׁקֶר, שֶׁהֵם סָמָאֵ\"ל וְנָחָשׁ, אִם יָבוֹאוּ לְהָעִיד עֵדוּת שֶׁל שֶׁקֶר עַל יִשְׂרָאֵל, שֶׁטָּעוּ בֵּין שֵׁשׁ לְשֶׁבַע, שֶׁהֵם אוֹתִיּוֹת ז\"וּ. וְזֶהוּ [ישעיה מג] עַם זוּ יָצַרְתִּי לִי תְּהִלָּתִי יְסַפֵּרוּ."],[9,"","וְלֹא יִתְיַחֵד ו' עִם ז' אֶלָּא בִּשְׂרֵפַת חָמֵץ, שֶׁבֵּין שָׁעָה שִׁשִּׁית לִשְׁבִיעִית. וְאַף עַל גַּב שֶׁמֵּהַתּוֹרָה הוּא עַד סוֹף שֵׁשׁ, גָּזְרוּ רַבּוֹתֵינוּ, אוֹכְלִין כָּל אַרְבַּע, וְתוֹלִין כָּל חָמֵשׁ, וְשׂוֹרְפִין בִּתְחִלַּת שֵׁשׁ. וּמְלַמְּדִים בַּעֲלֵי הַמִּשְׁנָה מֵעֵדוּת שֶׁל שְׁעוֹת הֶחָמֵץ לָעֵדוּת שֶׁל בְּדִיקוֹת הָעֵדִים שֶׁל אוֹתוֹ שֶׁהָרַג אֶת הַנֶּפֶשׁ. וְהַכֹּל מְפֹרָשׁ בַּמִּשְׁנָה. וִיקֻיַּם בָּהֶם, כִּי בַדָּבָר שֶׁחָשְׁבוּ מִצְרַיִם לָדוּן וְכוּ'. וְזֶהוּ וַעֲשִׂיתֶם לוֹ כַּאֲשֶׁר זָמַם. [דף ער\"ה ע\"ב]"]]],[["פִּקּוּדָא בָּתַר דָּא, לְקַבֵּל בֵּית דִּין הַגָּדוֹל עָלַיְיהוּ, בִּינָה, מִסִּטְרָא דִּגְדוּלָה אִקְרֵי אֱלֹהִים, בֵּית דִּין הַגָּדוֹל, רַב בְּדִינוֹי, וְרַב בְּזַכְווֹי, כְּגַוְונָא דְּאִתְּמַר שׂוֹם תָּשִׂים עָלֶיךָ מֶלֶךְ בְּפִקּוּדָא, שׂוֹם לְעֵילָּא, תָּשִׂים לְתַתָּא. הָכִי לְקַבֵּל עָלֵיהּ בֵּית דִּין רַבְרְבָא, אַף עַל גַּב דְּקַבִּיל עָלֵיהּ בֵּית דִּין זְעֵירָא. בֵּית דִּין זְעֵירָא, בֵּית דִּין שֶׁל שְׁלֹשָׁה, מִסִּטְרָא דִּשְׁכִינְתָּא תַּתָּאָה. בֵּית דִּין רַבְרְבָא, מֵאִלֵּין סַנְהֶדְּרֵי גְּדוֹלָה.","אָמַר בּוּצִינָא קַדִּישָׁא, שִׁבְעִים סַנְהֶדְּרֵי גְּדוֹלָה הֲווֹ, וְאַנְתְּ רַבְרְבָא עַל כֻּלְּהוּ, (שמות י״ח:כ״ב) וְהָיָה כָּל הַדָּבָר הַגָּדוֹל יָבִיאוּ אֵלֶיךָ וְכָל הַדָּבָר הַקָּטֹן יִשְׁפְּטוּ הֵם. אֵלּוּ. (הם סנהדרי גדולה, סנהדרי קטנה). סַנְהֶדְּרֵי גְּדוֹלָה מִסִּטְרָא דִּשְׁכִינְתָּא עִלָּאָה, סַנְהֶדְּרֵי קְטַנָּה מִסִּטְרָא דִּשְׁכִינְתָּא תַּתָּאָה.","מֹשֶׁה שׁוּשְׁבִינָא דְּמַלְכָּא, אַהֲרֹן שׁוּשְׁבִינָא דְּמַטְרוֹנִיתָא. וְעִמְּהוֹן שִׁבְעִין וּתְרֵין סַנְהֶדְרִין, כְּמִנְיַן חֶסֶד, וּמֵהָכָא סַנְהֶדְּרֵי גְּדוֹלָה. סַנְהֶדְּרֵי קְטַנָּה, מִסִּטְרָא דִּשְׂמָאלָא, (בראשית א׳:ט״ז) אֶת הַמָּאוֹר הַקָּטֹן לְמֶמְשֶׁלֶת הַלַּיְלָה.","וּבְגִין דָּא, תִּפְאֶרֶת אֶת הַמָּאוֹר הַגָּדוֹל לְמֶמְשֶׁלֶת הַיּוֹם, דְּאִתְּמַר בֵּיהּ (תהילים מ״ב:ט׳) יוֹמָם יְצַוֶּה יְיָ' חַסְדּוֹ. אֶת הַמָּאוֹר הַקָּטֹן לְמֶמְשֶׁלֶת הַלַּיְלָה, (שם) וּבַלַּיְלָה שִׁירֹה עִמִּי. שִׁיר דִּלְוִיִּים, וְדָא יְסוֹד. (שמואל א כ׳:ל״א) בֶּן יִשַׁי חַי עַל הָאֲדָמָה. דְּתָקִּין עֶשֶׂר מִינֵי תְּהִלִּים, בְּשִׁירָה. וְאִיהוּ צַדִּיק לִשְׂמָאלָא, אֶת הַמָאוֹר הַקָּטֹן, וְדָא שְׁכִינְתָּא, דְּאַתְנְטִילַת מִשְּׂמָאלָא. ע\"כ (יתרו כ\"ג, כבד את אביך וכו') כי תצור אל עיר וכו' עד בהאי עלמא נדפס בפרשת בלק דף קצ\"ו ע\"א."],[[0,"פקודא בתר דא וכו':","מצוה שלאחר זו, היא לקבל בית דין הגדול עליהם, היא בינה, שמצד החסד נקראת אלקים שהיא בינה, בית דין הגדול. כי גדול הוא חסד, גדול בדיניו שהוא שמאל, וגדול בזכיותיו שהוא ימין. כלומר, כשהשמאל דבינה כלולה בימין שהוא חסד, נקראים שניהם גדול. כמו שלמדנו במצוה, \u0003שום תשים\u0004 עליך מלך, אשר \u0003שום\u0004, הוא למעלה בבינה, \u0003תשים\u0004, הוא למטה במלכות. כך צריך לקבל עליו ב\"ד הגדול שמצד הבינה, אע\"פ שקבל עליו ב\"ד הקטן שמצד המלכות. ב\"ד הקטן, הוא ב\"ד של שלשה, שהוא מצד שכינה התחתונה, שהיא מלכות. בית דין הגדול מאלו, הוא סנהדרי גדולה, של ע\"ב. שהם שבעים סנהדרין וב' סופרים."],[1,"אמר בוצינא קדישא וכו':","אמר המאור הקדוש, שהוא ר\"ש, אל רעיא מהימנא, שבעים היו סנהדרי גדולה, ואתה הגדול על כולם. שכתוב, והיה כל דבר \u0003הגדול\u0004 יביאו אליך וכל הדבר \u0003הקטן\u0004 ישפטו הם, אלו הם סנהדרי גדולה וסנהדרי קטנה. שעליהם נאמר הדבר הגדול הדבר הקטן. סנהדרי גדולה הם מצד שכינה עליונה, שהיא בינה. סנהדרי קטנה הם מצד שכינה התחתונה, שהיא מלכות."],[2,"משה שושבינא דמלכא וכו':","משה הוא השושבין של המלך, ז\"א, אהרן, הוא שושבין של המלכה. ועמהם, הם ע\"ב סנהדרין, דהיינו ע' סנהדרין שעליהם משה ואהרן. שהם כמנין \u0003חסד\u0004, שהוא בגי' ע\"ב. ומכאן הם נקראים סנהדרי גדולה. כי חסד נק' גדול כנ\"ל. סנהדרי קטנה, הם מצד שמאל, שהיא מלכות הנבנית משמאל, שעליה כתוב, את המאור הקטן לממשלת הלילה."],[3,"ובג\"ד תפארת את וגו':","ומשום זה, תפארת שנקרא, את המאור \u0003הגדול\u0004 לממשלת היום, הוא משום שנאמר בו, יומם יצוה ה' \u0003חסדו\u0004. וכיון שהוא חסד ע\"כ נקרא המאור הגדול. את המאור הקטן לממשלת \u0003הלילה\u0004, היינו \u0003ובלילה\u0004 שירה עמי היינו שיר דלוים שזה יסוד שבמלכות בסו\"ה בן ישי \u0003חי\u0004 על האדמה, אשר \u0003ח\"י\u0004 הוא יסוד, האדמה היא מלכות, שהוא תקן עשר מיני שירה בתהלים. דהיינו אשרי שיר מכתם וכו'. (כנ\"ל פנחס אות רס\"ח). והוא צדיק שבשמאל, דהיינו יסוד שבמלכות, ושמאל \u0003את המאור הקטן\u0004, זו היא השכינה שנלקחה משמאל. כי השכינה נבנתה מקו שמאל דבינה במצב הא' (כנ\"ל ב\"א מאות ק\"י עד אות קט\"ו) וכן היא תמיד מבחינת שמאל."]],[[0,"","מִצְוָה אַחַר זוֹ – לְקַבֵּל בֵּית דִּין הַגָּדוֹל עֲלֵיהֶם. בִּינָה, מִצַּד הַגְּדֻלָּה נִקְרֵאת אֱלֹהִים, בֵּין דִּין הַגָּדוֹל, גָּדוֹל בְּדִינָיו, וְגָדוֹל בִּזְכֻיּוֹתָיו, כְּמוֹ שֶׁנֶּאֱמַר שׂוֹם תָּשִׂים עָלֶיךְ מֶלֶךְ, בְּמִצְוָה. שׂוֹם – לְמַעְלָה, תָּשִׂים – לְמַטָּה. כָּךְ לְקַבֵּל עָלָיו בֵּית דִּין הַגָּדוֹל, אַף עַל גַּב שֶׁקִּבֵּל עָלָיו בֵּית דִּין הַקָּטָן. בֵּין דִּין הַקָּטָן, בֵּית דִּין שֶׁל שְׁלֹשָׁה, מִצַּד הַשְּׁכִינָה הַתַּחְתּוֹנָה. בֵּין דִּין הַגָּדוֹל, מֵאֵלּוּ סַנְהֶדְרִין גְּדוֹלָה."],[1,"","אָמַר הַמְּנוֹרָה הַקְּדוֹשָׁה, שִׁבְעִים אִישׁ הָיוּ בְסַנְהֶדְרִין גְּדוֹלָה, וְאַתָּה הַגָּדוֹל עַל כֻּלָּם, [שמות יח] וְהָיָה כָּל הַדָּבָר הַגָּדל יָבִיאוּ אֵלֶיךְ וְכָל הַדָּבָר הַקָּטֹן יִשְׁפְּטוּ הֵם. אֵלּוּ [הם סנהדרין גדולה, סנהדרין קטנה]. סַנְהֶדְרִין גְּדוֹלָה מִצַּד הַשְּׁכִינָה הָעֶלְיוֹנָה, סַנְהֶדְרִין קְטַנָּה מִצַּד הַשְּׁכִינָה הַתַּחְתּוֹנָה."],[2,"","מֹשֶׁה שׁוֹשְׁבִין הַמֶּלֶךְ, אַהֲרֹן שׁוֹשְׁבִין הַמַּלְכָּה. וְעִמָּהֶם שִׁבְעִים וּשְׁנַיִם סַנְהֶדְרִין, כְּמִנְיַן חֶסֶד, וּמִכָּאן סַנְהֶדְרִין גְּדוֹלָה. סַנְהֶדְרִין קְטַנָּה מִצַּד הַשְּׂמֹאל, [בראשית א] אֶת הַמָּאוֹר הַקָּטֹן לְמֶמְשֶׁלֶת הַלַּיְלָה."],[3,"","וּמִשּׁוּם זֶה, תִּפְאֶרֶת – אֶת הַמָּאוֹר הַגָּדל לְמֶמְשֶׁלֶת הַיּוֹם, שֶׁנֶּאֱמַר בּוֹ [תהלים מב] יוֹמָם יְצַוֶּה ה' חַסְדּוֹ. אֶת הַמָּאוֹר הַקָּטֹן לְמֶמְשֶׁלֶת הַלַּיְלָה, [שם] וּבַלַּיְלָה שִׁירֹה עִמִּי. שִׁיר הַלְוִיִּם, וְזֶה יְסוֹד. [שמואל א כ] בֶּן יִשַׁי חַי עַל הָאֲדָמָה, שֶׁתִּקֵּן עֲשָׂרָה מִינֵי תְהִלִּים בְּשִׁירָה. וְהוּא צַדִּיק לִשְׂמֹאל, אֶת הַמָּאוֹר הַקָּטֹן, וְזוֹ שְׁכִינָה, שֶׁנּוֹטֶלֶת מֵהַשְּׂמֹאל."]]]]};
